INSERT INTO "acceptance_criteria" VALUES('AIK-001',1,'VM Goal/Plan/Task/Attempt와 AIK lease/placement의 단일 소유자 및 상호 참조 필드가 명시된다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-001',2,'AGS manifest 실제 경로·entrypoint·digest와 VM schema4/façade 계약을 확인하며 GUI schema2 예시 차이를 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-001',3,'문서상 구현·실행 미검증·호환 미완료를 구분한다. 첫 출시 matrix에 route_id·provider·auth_kind·role·required/optional·adapter 구현 상태·qualification 상태·사유·관측 시각·evidence_ref와 revision/digest를 기록한다. 두 벤더 및 API/지원 구독·총괄/worker 도구 실행이라는 DEC12 제안 범위와 필수 조합의 대응을 명시하며 범위 또는 upstream 변경 시 결정·영향·재검증 근거를 남긴다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-002',1,'VM React/TypeScript 화면·EngineClient 재사용 범위와 Tauri/대안의 선택 이유를 적는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-002',2,'창 표시→typed IPC→테스트 worker 호출→OS vault 왕복을 Windows에서 재현한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-002',3,'AIK 스택·엔진 runtime 버전·bundle 전략을 ADR에 명시하고 mock 성공을 제품 연동 성공으로 기록하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-003',1,'플랫폼별 지원 OS 버전·CPU·최소 자원과 선택한 설치 형식을 명시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-003',2,'개발 도구가 없는 환경에서 필요한 runtime을 어떻게 공급할지 검증한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-003',3,'서명·업데이트 신뢰·제거 후 데이터 처리 기준을 정하며 macOS는 첫 출시 gate로 넣지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-004',1,'GUI renderer가 arbitrary shell·전체 filesystem·raw secret API에 직접 접근하지 않는다. API 제한 도구 경로와 trusted same-user native 경로의 OS principal·trust profile을 구분하며 앱 IPC 제한을 OS 프로세스 격리로 광고하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-004',2,'명령마다 schema·발신자·workspace·request_id를 검증하고 응답에 민감 값을 넣지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-004',3,'호환되지 않는 frontend/backend 버전은 구체적인 연결 오류로 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-005',1,'pool/credential_ref/profile/placement/lease와 VM/AGS 외부 ID를 저장하고 실비밀·VM 권위 Task 사본은 저장하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-005',2,'원자적 쓰기와 revision 충돌 처리가 동작하고 손상/마이그레이션 실패 시 원본을 보전한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-005',3,'제품 운영 데이터가 planning/backlog.sqlite3 또는 Git 추적 경로에 기록되지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-006',1,'같은 사용자/workspace에서 GUI를 두 번 열어도 동일 총괄 인스턴스에 연결한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-006',2,'창 닫기·작업 일시정지·앱 완전 종료의 동작을 분리한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-006',3,'앱 종료 시 신규 배치를 중지하고 실제 진행 중 job은 재시작 때 관측 대상으로 남긴다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-007',1,'workspace·연결·총괄/worker 프로필·동시성/예산 값을 구분해 저장한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-007',2,'다른 workspace의 연결 참조와 유효하지 않은 설정을 검증 단계에서 차단한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-007',3,'설정 내보내기는 비밀 값을 제외하고 import 후 인증이 필요한 연결을 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-008',1,'현재 compatible/incompatible/unverified 상태와 manifest·버전·digest를 진단 결과로 남긴다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-008',2,'첫 출시 지원 matrix에 따라 A2 호환 plugin과 각 runtime의 model/effort 관측을 AIK-081/082에 연결한다. 개별 미지원 경로와 다른 qualified 경로의 상태를 분리한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-008',3,'문서·mock 통과만으로 실제 gate를 PASS 처리하지 않으며 실행불가 원인을 GUI가 소비할 수 있게 반환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-009',1,'플랫폼별 backend(Windows: Credential Manager 또는 사용자 범위 DPAPI, Linux: Secret Service)를 검증해 선택하고 머신 공유 범위를 기본으로 사용하지 않는다. 저장 보호·다른 OS 사용자 경계와 동일 사용자 native 프로세스의 직접 접근 범위를 ADR에 명시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-009',2,'저장·교체·삭제와 앱 재시작 후 참조 회수가 동작한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-009',3,'SQLite·설정·로그·지원 번들에서 테스트 비밀 평문이 검출되지 않으며 저장소 접근 실패를 정확히 반환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-010',1,'provider/account label/auth_kind/execution_kind/credential_ref와 확인 시각을 저장한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-010',2,'동일 벤더 구독/API를 별도 등록하고 connection_id별 공식 호스트·프로필·비민감 계정 binding revision을 연결한다. 등록한 계정과 실행할 인증 문맥의 일치를 검증한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-010',3,'이름 변경으로 기존 task provenance가 바뀌지 않고 사용 중 연결 삭제는 영향 범위를 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-011',1,'auth 연결 성공과 job 실행·관측·중단 지원을 별도 capability로 반환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-011',2,'공식 호스트의 계정별 인증 context 격리 지원을 capability로 반환한다. 격리 불가 호스트의 충돌 동시 사용과 다른 계정으로의 묵시적 전환을 막고 구독 인증을 API 키로 변환하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-011',3,'벤더 고유 오류·rate limit·확인 불가능 상태를 보존하는 표준 오류를 정의한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-012',1,'키 등록·인증 확인·모델 호출·교체·해제의 코드 경로를 구현하고 성공 및 실패 protocol fixture를 통과한다. 미지원 응답만 반환하는 stub은 구현 완료가 아니다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-012',2,'provider request/job·model·usage와 도구 요청/결과 메시지를 공통 계약으로 변환하며 AIK-035의 bounded agent tool loop에 연결 가능하다. fixture 결과를 provider 실측으로 기록하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-012',3,'잘못된 키/권한/모델을 실행 가능 자원으로 광고하지 않고 구독 잔여량과 API 과금을 구분한다. adapter 구현 상태와 route qualification 상태를 별도로 보관하며 실제 지원은 AIK-022/082/086의 단계별 근거로만 판정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-013',1,'키 등록·인증 확인·모델 호출·교체·해제의 코드 경로를 구현하고 성공 및 실패 protocol fixture를 통과한다. 미지원 응답만 반환하는 stub은 구현 완료가 아니다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-013',2,'provider model·usage·cache 및 API 도구 요청/결과 메시지를 공통 계약으로 변환한다. 잘린 결과를 완료로 승격하지 않고 AIK-035의 agent tool loop와 연결 가능하며 fixture 결과를 실측으로 기록하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-013',3,'401/429/timeout과 모델 불가 상태를 공통 오류로 노출한다. adapter 구현 상태와 route qualification 상태를 분리하고 실제 지원은 AIK-022/082/086의 단계별 근거로만 판정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-014',1,'GUI command에 대응하는 공식 인증 시작·상태 회수·재연결·해제 코드 경로를 구현하고 성공/실패 host fixture를 통과한다. unsupported만 반환하는 stub이나 fixture 통과를 실제 로그인 성공으로 기록하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-014',2,'공식 호스트 소유 인증은 host handle로 연결하며 원문 토큰을 범용 API 비밀로 재사용하지 않는다. host absent/unsupported와 인증 만료를 별도 capability로 반환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-014',3,'기존 VM runtime을 재사용하고 실행 전 비민감 계정 binding revision을 대조한다. 외부 로그인 변경은 stale/재연결로 표시하며 bridge 구현·실제 auth 성공·governed 적합성을 구분한다. 라이브 근거는 AIK-022 인증·082 사전 probe·086 governed qualification으로 연결한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-015',1,'공식 인증 시작·상태 확인·실행 요청·해제·재연결의 코드 경로를 구현하고 성공/실패 host fixture를 통과한다. unsupported만 반환하는 stub이나 fixture 통과를 실제 실행 성공으로 기록하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-015',2,'호스트의 로그인 비밀을 이중 복제하지 않고 host handle과 capability를 보관한다. host absent/unsupported와 인증 만료를 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-015',3,'configured catalog와 runtime 실측을 분리하고 선택 계정 binding을 검증한다. 외부 로그인 변경·계정 격리 불가를 capability/재연결 필요로 표시한다. bridge 구현과 라이브 지원 판정을 분리하고 실제 근거는 AIK-022 인증·082 사전 probe·086 governed qualification으로 연결한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-016',1,'만료/잠금/해제 자원은 신규 배치에서 제외하고 재인증 후 재검증한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-016',2,'키 교체 뒤 새 실행은 새 참조 버전을 사용하며 이전 실행은 실제 상태를 회수한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-016',3,'사용자가 설정한 vault 잠금·OS 세션 잠금(Windows 세션 잠금·Linux logind LockedHint) 정책이 동작하고 강제 로그아웃을 완료/환불로 간주하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-017',1,'prompt/IPC response/PEER/evidence/log/crash support bundle에 테스트 비밀이 남지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-017',2,'부분 키·Authorization 헤더·중첩 오류 객체·URL query에 대한 제거 규칙을 검증한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-017',3,'redaction 후에도 connection/task/request ID로 오류와 감사 이력을 추적할 수 있다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-018',1,'총괄과 worker에는 connection_id 또는 credential_ref만 전달한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-018',2,'허용된 adapter·workspace·작업 범위가 일치할 때만 broker 경로에서 비밀을 해석하고 임의 열람 요청을 거절한다. 같은 OS 사용자 native 프로세스의 직접 저장소 접근까지 이 검사로 격리된다고 주장하지 않으며 해당 경로의 trust profile을 연결한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-018',3,'비밀을 명령행 인수나 지속 설정파일에 남기지 않고 자식 프로세스 전달·정리 범위를 검증한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-019',1,'pool_id와 connection_id를 분리하고 같은 모델의 구독/API 경로를 각각 조회한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-019',2,'adapter 구현 상태·auth 계정 binding·runtime 지원·governance 적합성·최종 확인 시각·matrix revision을 별도 필드로 노출한다. 외부 로그인 변경은 재검증하며 선택 경로 unsupported가 다른 qualified 경로를 덮지 않는다. 구현 완료만으로 실행 가능 광고를 하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-019',3,'오래되거나 확인할 수 없는 값은 unknown/stale로 표시하며 0이나 무제한 용량으로 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-020',1,'모델 이름을 제품 코드에 고정하지 않고 자원별 목록/검증된 수동 등록을 지원한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-020',2,'추론 수준·도구·context 제한 등 확인 가능한 항목의 출처와 시각을 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-020',3,'requested/provider_observed/configured_catalog/local_derived를 구분하며 이름이 같다고 capability를 동일 취급하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-021',1,'workspace가 사용할 연결을 명시하고 미허용 connection 참조를 차단한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-021',2,'내보낸 설정은 API 키나 공식 호스트 토큰을 포함하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-021',3,'새 사용자/기기에서 해석할 수 없는 비밀 참조는 재인증 필요 상태로 복원한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-022',1,'동일 matrix revision의 필수 API/지원 구독 인증 경로마다 지원 플랫폼마다 실제 등록·호출·회전·해제·재연결을 통과한다. 같은 벤더의 두 연결과 외부 로그인 변경에서 다른 계정으로 묵시 실행되지 않는다. adapter fixture만으로 이 기준을 통과하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-022',2,'다른 사용자·잠금·손상된 참조·인증 만료·로그 제거 조건을 합성 비밀로 검증한다. 실제 계정 비밀은 장부/검증 산출물에 저장하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-022',3,'auth 성공과 governed 실행 준비 여부를 별도 판정한다. 선택/미지원 경로의 사유·관측 시각·NOT_RUN 및 근거를 기록하며 필수 경로가 미지원/미검증이면 이 태스크는 완료할 수 없다. matrix 변경은 결정·영향·재검증 기록을 요구한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-023',1,'총괄 실행 자원·모델·지원 effort·도구·호출 한도와 허용 대체 프로필을 저장한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-023',2,'총괄 설정을 바꾸어도 worker/검토자 프로필은 덮어쓰지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-023',3,'실행 직전 실제 capability를 검증하고 요청 프로필과 실제 binding/provenance를 함께 남긴다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-024',1,'worker 배치 없이도 총괄 연결을 먼저 검증·시작할 수 있다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-024',2,'프로필 미설정 또는 실행불가 사유가 있으면 설정이 필요한 항목을 명확히 반환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-024',3,'중복 시작을 막고 시작/정지/실패와 실제 모델·effort 관측을 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-025',1,'메시지 ID·목표 ID·event cursor를 기록하고 동일 이벤트를 중복 처리하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-025',2,'실행 결과·오류·사용자 추가 지시에 반응하며 유휴 상태에서 무한 model 호출을 하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-025',3,'앱 재시작 후 미처리 항목을 회수하고 처리 ACK와 작업 완료를 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-031',1,'Goal/Plan/Task 수정은 공개 command만 사용하고 VM DB를 AIK가 직접 SQL로 변경하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-031',2,'request/goal/task/attempt ID, revision, digest, history cursor와 기존 인가를 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-031',3,'STALE_EXECUTION_INPUT·EXTERNAL_UNKNOWN 등 원래 오류 의미를 유지한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-029',1,'이미 허용된 작업은 기존 범위를 전달하며 불필요한 반복 승인을 요구하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-029',2,'작업 대상·효과·입력 revision이 인가 범위를 벗어나는 경우 VM/AGS 계약대로 처리한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-029',3,'총괄·worker·원격 peer가 자신에게 새 권한을 부여하거나 완료 판정을 덮어쓸 수 없다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-026',1,'Goal/Plan/Task는 VM 공개 명령으로 생성·변경하고 별도 DAG 엔진을 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-026',2,'권한 범위 안의 준비된 작업을 요청하고 blocked/unknown/validation 결과에 따라 다음 행동을 결정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-026',3,'모델의 응답 종료와 Goal 완료를 구분하며 VM verdict/evidence를 근거로 보고한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-027',1,'사용자 원문 지시와 후속 정정의 순서·적용 범위를 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-027',2,'문맥을 줄여도 미완료 목표·허용 범위·검증 근거는 권위 원장 참조로 회수한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-027',3,'재개 시 새 Goal/Attempt를 무조건 만들지 않고 기존 ID·revision으로 이어간다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-028',1,'진행 중 호출 종료/취소와 새 binding 적용 시점을 정하고 같은 이벤트를 이중 처리하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-028',2,'사용자가 설정한 대체 프로필과 품질·도구·데이터·예산 범위를 만족하는 경우만 전환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-028',3,'변경 이유·이전/새 모델·실제 effort·checkpoint를 기록하고 worker 프로필은 유지한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-040',1,'총괄 호출을 포함해 자원/목표별 금액·토큰·시간·동시성 상한을 검사한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-040',2,'구독 quota와 API 비용을 별도 단위로 보관하며 추정/확정/unknown을 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-040',3,'한도 도달 시 신규 배치를 멈추고 지연 usage를 정산한다. provider 외부 청구의 절대 상한을 보장한다고 표현하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-081',1,'A2 same-user profile·manifest entrypoint·key/pin/digest 계약이 VM 기대와 맞는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-081',2,'호환 배포물의 provenance와 conformance PASS 증거가 확보되기 전 완료 처리하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-081',3,'upstream 수정 필요 시 해당 저장소 변경/릴리스 참조를 남기고 AIK 구현 완료와 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-082',1,'001 matrix의 필수 API/구독 경로를 실제 최소 진단 probe로 호출해 모델/지원 effort·계정 binding·receipt와 계약 가능성을 확인한다. 012~015 구현/fixture를 live 성공으로 기록하지 않으며 전체 035/086의 governed agent loop를 이 사전 태스크의 선행 조건으로 요구하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-082',2,'Codex 관측 gap·GOVERNANCE_PROVIDER_UNSUPPORTED와 Claude configured catalog/실측 차이 등 필수 계약 불충족은 upstream 해결 artifact와 재검증을 확보할 때까지 차단한다. 미관측 값을 추정하지 않고 선택 unsupported/NOT_RUN은 필수 경로와 별도 상태로 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-082',3,'결과 상태는 probe_verified이며 운영 qualified가 아니다. 019/033의 고정 test-only candidate를 이용해 기존 인가·한도·A2/VM gate를 유지하는 086 검증을 준비한다. 일반 운영 자원 광고는 086 PASS 뒤에만 가능하고 matrix 변경은 결정·영향·재검증 근거를 남긴다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-032',1,'before_execution/before_completion gate를 모두 통과해야 governed 작업이 진행된다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-032',2,'필수 관측이 없거나 A2/manifest가 불일치하면 이유를 노출하고 gate를 생략하는 fallback이 없다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-032',3,'AGS gate와 conformance 결과 재사용은 VM의 기존 공개 경로를 사용한다. AIK에 별도 판정/cache·Task 완료 권위를 만들지 않으며 AGS gate는 VM Core 판정의 추가 조건이다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-030',1,'JEV/대체 분류 경로의 실제 인터페이스·버전·배포 상태를 확인하고 미완료이면 upstream 변경 참조와 차단 사유를 기록한다. RAW를 보존하고 앞단 별도 LLM 정형화 없이 확인된 metadata만 공통 REQ에 담는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-030',2,'JEV 분류·평가 결과와 실제 AGENT의 최종 스킬 선택을 별도 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-030',3,'OFF/호출 불가 시 해당 벤더 품질 기준을 통과한 최저비용 분류 후보 및 기존 운영 계약을 따르고 선택을 강제하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-033',1,'VM의 ready/인가 판단을 입력으로 사용하고 별도 Task DAG/재시도 권위를 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-033',2,'AGS/실제 AGENT 및 VM 역할 계약이 요구한 모델·host·전문역량과 데이터 범위에 맞는 pool만 선택한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-033',3,'독립 작업만 병렬 후보로 만들되 동일 프로젝트 Attempt는 VM의 직렬 기본을 유지한다. 해당 경로의 동시 실행 capability와 qualification 근거가 있을 때만 병렬 배치하고 이유·inventory revision을 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-034',1,'한정된 pool capacity와 예산 예약을 경쟁 요청에서도 초과 점유하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-034',2,'lease는 VM task/attempt와 pool/worker를 참조하고 오래된 owner의 상태 갱신을 거절한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-034',3,'만료와 실제 provider 종료를 구분하며 살아 있는 불명확 job은 즉시 재발사하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-035',1,'request_id/contract digest/attempt/lease/provider job identity를 연결한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-035',2,'예약 완료·전송 ACK·실제 실행 시작을 별도 상태로 남긴다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-035',3,'native 경로는 기존 VM runtime을 재사용하고 관측된 실제 권한과 trusted same-user 여부를 기록한다. API 경로는 도구 요청→AIK-029 권한 gateway→VM/AGS 공개 command 또는 허용 도구→결과 반환→후속 모델 호출을 수행한다. 제한 도구 경로와 native OS 권한을 혼동하지 않으며 budget/중단·기존 Task/재시도 권위를 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-036',1,'provider observed 모델/effort/job 상태와 요청 설정을 분리해 저장한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-036',2,'이벤트 cursor gap과 중복을 감지하고 재조회로 복원한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-036',3,'usage 미제공과 실제 0을 구분하고 부분 출력이나 HTTP 성공만으로 완료 처리하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-037',1,'artifact identity·SHA256·생성 attempt·접근 범위를 저장한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-037',2,'같은 callback의 동일 결과는 dedup하고 다른 digest는 충돌로 처리한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-037',3,'필수 근거 접근·무결성을 확인하고 권위 evidence identity/digest를 보존한다. 비밀 제거된 표시용 산출물은 별도 derivative identity/digest와 변환 provenance로 기록한다. 원본 보관이 정책상 불가하면 처음부터 비밀 없는 근거를 생산한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-038',1,'사용자 중단 즉시 신규 예약을 막고 실행 중 job은 adapter 지원 계약대로 처리한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-038',2,'취소 요청과 취소 확인/늦은 성공을 구분하고 usage·evidence를 최종 회수한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-038',3,'자체 생성 worker만 종료하며 빌려 쓰는 기존 호스트는 사용권을 반환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-039',1,'저장된 attempt/lease/provider job을 VM 상태와 대조하고 실제 관측으로 회복한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-039',2,'외부 효과가 불명확하면 무조건 재실행하지 않고 VM의 unknown/retry 계약을 따른다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-039',3,'recover/retry/cancel 판단 이유·revision·원래 evidence를 덮지 않고 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-041',1,'VM의 실행 가능 상태와 프로젝트별 동시 실행 capability를 우선 적용한다. qualification을 통과한 범위에서 제약 내 worker를 확보하고 최소 한 지원 시나리오의 복수 worker 실제 동시 실행을 검증한다. 직렬 전용 경로의 제약은 유지한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-041',2,'작업 완료/실패 뒤 evidence·usage를 회수하고 유휴 lease와 자체 생성 프로세스를 정리한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-041',3,'worker가 전 용량을 점유해 총괄·취소/관측 경로가 멈추지 않도록 제어용 여유를 보장한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-042',1,'provider success·ACK·validation·audit·GoalVerdict를 서로 다른 상태로 다룬다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-042',2,'필수 독립검토는 별도 역할·실행 provenance를 기록하고 자기 완료 선언을 감사 통과로 승격하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-042',3,'VM 최종 권위와 기존 인가 범위를 유지하며 후속 재작업 사유를 회수한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-043',1,'VM Goal/Task/Attempt, AGS workflow/peer/session, AIK placement/lease를 연결한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-043',2,'읽기 projection은 재생 가능하고 VM의 권위 원장으로 사용되지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-043',3,'AGS 로컬 PEER의 전달/claim/ACK/result와 worker 주소를 연결하며 같은 사용자 범위를 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-044',1,'실제 총괄/VM 준비 경로가 RAW Goal 하나에서 A/B 독립 작업과 두 산출물을 소비하는 C를 구성한다. 두 벤더의 qualified 자원이 선택 프로젝트에서 실제 파일 생성·수정과 한정 검증 명령을 수행하며 harness가 Plan/Task/완성 출력을 미리 주입하지 않는다. VM 직렬 기본과 해당 경로의 qualified 동시성 조건을 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-044',2,'독립 검사의 의도된 실패 한 번을 기존 인가·VM 재작업 절차로 수정해 최종 Goal Test를 통과한다. worker가 수정할 수 없는 사전 고정 oracle로 결과 bytes/내용·명령 exit/output·입력 digest를 대조하고 실제 model/effort/job·usage·AGS 검사·VM verdict를 연결한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-044',3,'동일 지원 matrix의 필수 runtime/역할/도구 계약은 086의 실제 qualification을 모두 충족하고 대표 합성 목표로 연결한다. 선택 unsupported와 필수 FAIL/NOT_RUN을 구분하며 후자는 차단한다. worker 반환·재시작 뒤 같은 산출물을 열고 해시/내용·lease 반환·중복 효과 없음까지 확인한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-045',1,'연결 관리·총괄·Goal·worker·근거·사용량·설정 화면으로 이동할 수 있다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-045',2,'실제 typed client/read model을 사용하고 mock 화면을 운영 상태로 표시하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-045',3,'엔진 연결 불가/버전 불일치/오래된 상태를 사용자가 이해할 수 있게 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-046',1,'벤더·계정·구독/API 실행 경로를 선택하고 공식 인증 흐름을 시작/완료한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-046',2,'API 키 입력은 마스킹하고 저장 후 실비밀을 화면 상태에 유지하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-046',3,'연결 확인→총괄 모델 설정으로 이어지며 만료/취소/오류 후 재시도 지점을 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-047',1,'계정 별칭·벤더·인증 유형·연결 상태·최종 확인 시각·사용 범위를 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-047',2,'연결 검사·키 교체·로그아웃·재인증·삭제를 GUI에서 수행한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-047',3,'원문 비밀과 민감 오류는 표시하지 않고 잠금 상태와 진행 중 작업 영향을 보여준다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-048',1,'같은 모델의 구독/API 경로를 별도 자원으로 비교한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-048',2,'실행·관측·취소·재연결·effort 지원과 검증 시각/출처를 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-048',3,'관측 불가 잔여량과 미지원 경로를 0이나 정상 상태로 표시하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-049',1,'연결 자원→모델→지원 effort/도구→한도/대체 정책을 설정하고 총괄을 시작한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-049',2,'총괄과 worker/검토 역할을 독립 설정하고 requested/actual applied를 구분해 보여준다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-049',3,'실행 중 변경은 checkpoint/교체 상태와 적용 이유를 보여주며 유효하지 않은 조합을 실행 전에 안내한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-050',1,'원문 목표/후속 지시를 보존해 전달하고 해당 Goal/이벤트 ID로 연결한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-050',2,'응답 스트림 종료와 작업 완료를 구분하며 목표의 현재 단계·필요한 사용자 입력을 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-050',3,'창을 다시 열면 같은 대화·목표·미처리 지시를 복원하고 중복 제출을 막는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-051',1,'Goal/Plan revision/Task/Attempt와 선행 작업을 조회한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-051',2,'ready/running/blocked/unknown/result/verified 상태를 구분하고 담당·근거를 탐색한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-051',3,'변경과 실행 명령은 VM façade를 통하며 GUI가 직접 완료 상태를 쓰지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-052',1,'worker 역할·벤더·host·요청/실제 모델·effort·Task·lease·마지막 갱신을 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-052',2,'active/reserved/draining/released/unknown과 병렬도·사용량을 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-052',3,'개별/목표 단위 중단 요청과 실제 취소 확인을 별도 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-053',1,'기존 허용 범위를 다시 묻지 않고 새 판단이 필요한 작업만 노출한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-053',2,'대상·변경/외부 효과·예산·입력 revision과 근거를 확인한 뒤 승인/거절한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-053',3,'사용자 identity·승인 범위·시각을 기록하고 중복 클릭이나 stale approval을 새 권한으로 사용하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-054',1,'VM verdict와 연결된 파일·digest·생성 attempt·검토 결과를 조회한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-054',2,'Markdown/HTML/링크 표시가 임의 스크립트·프로세스·파일 실행 권한을 획득하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-054',3,'근거 접근 실패를 표시하고 지원 번들에 비밀 값이 포함되지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-055',1,'총괄과 worker의 일반/캐시/출력 토큰 및 비용을 지원되는 범위에서 분리한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-055',2,'구독 quota를 API 금액으로 합산하지 않고 unknown·추정·확정과 갱신 시각을 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-055',3,'목표/자원 한도를 GUI에서 설정하고 신규 실행 중지 사유를 이해할 수 있게 보여준다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-056',1,'창 닫기·백그라운드 유지·일시정지·완전 종료가 정해진 정책과 표시대로 동작한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-056',2,'OS 재로그인·재접속 때 기존 인스턴스·목표를 복원하고 중복 총괄을 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-056',3,'한글 경로/IME·키보드 탐색·가독성·지원 DPI에서 주요 흐름을 사용할 수 있다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-057',1,'필요한 GUI/엔진/runtime 의존성이 고정 provenance와 함께 제공된다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-057',2,'사용자별 설정/데이터 경로를 사용하고 비밀·개발 계정·운영 DB를 설치물에 넣지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-057',3,'설치·첫 실행·정상 제거가 동작하고 선택한 서명/무결성 정책을 적용한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-058',1,'AIK 데이터 migration 실패 시 원본을 유지하며 VM 원장 migration 정책을 임의로 변경하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-058',2,'연결 metadata·프로필·작업 참조가 보존되고 해석 불가능한 비밀은 재인증 필요로 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-058',3,'업데이트 출처/무결성을 검증하고 실행 중 worker 처리·재개 정책을 적용한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-059',1,'GUI에서 두 벤더 인증→실제 사용자 프로젝트 선택/생성→총괄·개발·검토 모델 지정→RAW Goal 제출을 수행한다. 044의 A/B→C 생성·수정·한정 검증 명령·독립 실패 후 재작업을 같은 설치본에서 실행하고 후속 정정을 올바른 Goal/revision에 연결한다. 사용자가 CLI로 Plan/Task/입력/완성 산출물을 사전 구성하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-059',2,'같은 installer hash/runtime manifest/지원 matrix의 필수 API/지원 구독·역할·도구 조합을 실제 검증한다. requested/observed model·effort·계정·VM/AGS 판정·usage를 대조하고 최종 파일을 열기/저장해 외부 고정 oracle와 bytes/digest를 확인한다. 필수 FAIL/NOT_RUN은 차단하고 선택 unsupported는 정확히 안내한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-059',3,'창 닫기/재열기·앱 재시작·중단/재개 뒤 같은 Goal/미처리 지시/진행 job을 복원하고 worker/lease 반환 뒤에도 결과를 사용한다. 088의 설정 이동·전체 백업·업데이트 실패 복구·새 사용자 복원과 재인증을 GUI/설치 복구 화면으로 완료한다. 혼합 checkpoint·stale 입력·중복 효과·미해결 unknown을 성공으로 표시하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-060',1,'전달 전/후 crash·callback 중복/역전·취소 경쟁·unknown 결과를 재현한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-060',2,'auth expiry·budget exhausted·capacity 고갈·stale input에서 신규 실행과 재시도를 통제한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-060',3,'검증 실패/근거 부족을 완료로 표시하지 않고 회복 뒤 같은 외부 효과를 중복 실행하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-061',1,'합성 비밀로 vault·로그·prompt·IPC·support bundle의 노출을 점검하고 broker 범위 거부·다른 OS 사용자 접근·native 실행 principal과 실제 권한을 확인한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-061',2,'결과 화면 콘텐츠/임의 IPC가 앱의 실행·시크릿 권한을 우회하지 못함을 검증한다. OS 격리를 광고한 경로는 실제 경계를 시험하며 trusted same-user 경로의 통과를 강한 프로세스 격리 PASS로 기록하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-061',3,'AGS/VM qualification과 AIK GUI 출시 판정을 분리하고 발견 결함의 해결 증거를 남긴다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-062',1,'queue/startup/inference/gather/audit와 전체 완료 시간을 구분한다. VM 프로젝트별 직렬 제약을 유지하며 병렬 비교는 해당 capability qualification 근거가 있는 경로에서만 수행한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-062',2,'총괄/worker 토큰·실제 비용·캐시 사용량을 지원 범위에서 측정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-062',3,'병렬 속도 향상과 비용 절감은 각각 실측 결과로 판정하고 GUI 정지/메모리 과다 기준을 확인한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-063',1,'연결·모델 지정·목표 실행·중단·재연결·오류 해결을 실제 화면 기준으로 설명한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-063',2,'지원 matrix revision/digest에 따라 구현 상태와 실지원/미지원/NOT_RUN 경로, 확인 불가 usage, 데이터 보관/삭제 및 native same-user 신뢰 범위를 안내한다. 문서의 지원 주장은 실제 qualification 근거와 일치한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-063',3,'AIK 자체 라이선스를 확정하고 배포하는 upstream 구성요소의 notice를 포함한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-064',1,'같은 installer identity/runtime manifest와 지원 matrix revision/digest에 P01~P10, 두 벤더 합성 개발 E2E·필수 인증/runtime/역할/도구 live evidence·upstream conformance·일관 복원·독립 검토·측정 기준 결과를 연결한다. 개발 패키지나 이전 빌드 근거만으로 설치본 결과를 대체하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-064',2,'이 gate 자체를 제외한 현재 first_release 태스크 전체와 각 필수 사용자 흐름이 완료돼야 한다. 필수 경로 FAIL/미지원/NOT_RUN, oracle 불일치, 미해결 중대 결함은 출시를 차단한다. 선택 경로 결과는 별도 보관하고 범위·판정 기준 변경은 결정·영향·재검증 없이 gate를 완화할 수 없다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-064',3,'선택된 서명/무결성·지원 환경·알려진 제한과 배포물 hash를 포함해 출시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-065',1,'provider/model/account/workspace/TTL별 cache 경계를 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-065',2,'실제 usage와 가격/credit 출처·시각에 따라 지연·비용·기한 정책을 적용한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-065',3,'크레딧 소진 자체를 목표로 무관한 작업을 만들지 않고 기존 budget/품질 조건을 유지한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-066',1,'생성/재연결/관측/취소/종료/usage 지원 범위를 실행 경로별로 확인한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-066',2,'직접 생성 worker와 기존 세션 사용권을 구분해 lease/release한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-066',3,'생성 API가 없는 경로는 unsupported로 표시하고 로컬 성공을 Cloud 성공으로 대체하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-067',1,'hello/capability/offer/accept/result/cancel/lease 메시지와 schema 협상을 정의한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-067',2,'상호 인증·짧은 작업 권한·key rotation/revoke·재전송/만료 조건을 정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-067',3,'VM Goal 권위, 전역 cluster placement, 로컬 pool/lease의 소유자·복구 규칙을 명시한다. Task 입력 manifest의 논리 대상 ID·source revision·상대경로·내용 digest·허용 artifact 참조와 수신 경로 projection·입력 준비 책임을 정의한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-068',1,'cluster_id와 신뢰 identity를 연결하고 양쪽이 허용한 scope를 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-068',2,'provider 자격증명 원문을 교환하지 않고 작업 위임 권한만 사용한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-068',3,'peer 회수/인증 만료 뒤 신규 위임을 중단하고 진행 중 실행의 관측/복구를 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-069',1,'message/task/attempt/lease ID·contract digest·deadline을 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-069',2,'전송 성공·처리 ACK·실행 완료를 구분하고 ACK 손실을 재실행 권한으로 쓰지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-069',3,'재연결 시 cursor/sequence로 복구하며 만료·replay·호환불가 메시지를 거절한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-070',1,'모델 능력·도구·검증 등급·용량·비용 힌트·데이터 범위와 갱신 시각을 교환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-070',2,'원문 secret·내부 계정·private filesystem 경로를 광고하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-070',3,'오래된 광고를 배치 확정으로 신뢰하지 않고 수락 시 로컬에서 용량·정책을 재검사한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-071',1,'상위 Goal/Task/contract revision·input manifest digest를 하위 lease/실행 identity에 결속한다. 허용 artifact만 수신 측 허용 root에 준비하고 bytes/digest/freshness를 실행 전에 검증한다. 원본 논리 대상과 수신 경로 projection을 구분하며 VM 권위를 복제하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-071',2,'하위가 로컬 정책·capability·capacity와 입력 접근권한을 재검사한다. 상대경로 탈출·symlink 우회·누락·변조·stale 입력은 실행 전에 거절하고 구체 사유를 반환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-071',3,'budget·권한·데이터 범위를 위임 시 축소할 수 있으나 임의 확대하거나 새 Task 권위를 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-072',1,'결과의 원격 attempt·lease·model provenance·artifact digest를 대조한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-072',2,'원시 private 경로나 credential 원문을 전달하지 않고 범위가 제한된 artifact 접근을 사용한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-072',3,'상위는 하위 완료 선언만으로 완료하지 않고 필요한 근거·검증/정산을 회수한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-073',1,'fencing token과 실행 identity를 수신 측에서 검증한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-073',2,'lease 만료/peer offline과 provider job 종료를 구분하고 unknown 실행을 먼저 관측한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-073',3,'coordinator 회복·취소 경합·재위임에서 단일 권위와 기존 evidence를 유지한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-074',1,'각 클러스터가 자기 credential로 실행하며 offer/accept/ACK/result/audit를 구분한다. 송신 측에만 있는 파일과 선행 산출물을 빈/다른 root에 준비한 뒤 수신 bytes/digest·Task 입력 binding을 확인하고 실제 읽기 Task를 실행한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-074',2,'단절·중복/역전 callback·취소·재시작 후 결과와 권위를 회복한다. 누락·변조·stale·접근불가 입력은 실행/완료를 차단하며 재조회로 사유와 입력 identity를 확인한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-074',3,'양측 실제 모델·usage·근거·lease 반환을 확인하고 로컬 mock을 원격 성공으로 기록하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-075',1,'GUI에서 peer 연결/회수·capacity·위임 상태·원격 근거·unknown 사유를 조회한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-075',2,'전송/queue/startup/실행/gather/감사 비용과 시간을 분리 측정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-075',3,'성공 범위·실패 복구·신뢰/데이터 범위와 측정 조건을 문서화한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-076',1,'endpoint·모델·tool/effort 지원을 검증해 inventory에 등록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-076',2,'로컬이라는 이유로 도구 권한·품질·VM/AGS gate를 생략하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-076',3,'GUI에서 장착→역할 지정→작업→근거 회수를 수행하고 GPU/메모리 한도를 설정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-077',1,'벤더별 모델 이름·effort·인증을 공통 contract에 매핑하되 차이를 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-077',2,'conformance를 통과한 capability만 실행 가능한 inventory로 광고한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-077',3,'최소 한 추가 자원의 GUI 등록과 실제 governed E2E 근거를 확보한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-078',1,'총괄/개발/검토 프로필과 최소 품질·budget·fallback 조건을 표현한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-078',2,'설정 적용은 preview와 revision을 남기고 기존 Goal 인가 범위를 임의 확대하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-078',3,'JEV 분류 보조와 실제 AGENT의 최종 스킬 선택은 그대로 유지한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-079',1,'사람/agent/cluster identity와 허용 위임 범위를 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-079',2,'조직 간 provider secret을 공유하지 않고 작업 계약·capability만 교환한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-079',3,'데이터 등급·증거 열람·회수·동시성/예산 경계를 양측에서 검증한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-080',1,'AIK의 이름을 Kubernetes API 호환 주장으로 사용하지 않고 연결 범위를 명시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-080',2,'실제 배포 자원과 worker/lease identity를 연결하며 기존 VM/AGS 권위와 인증 경계를 보존한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-080',3,'데스크톱 GUI 첫 출시 의존성에 이 adapter나 Kubernetes 운영을 추가하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-083',1,'P01~P10의 첫 출시(지원 플랫폼별) 흐름과 P11 연합/P12 확장의 최소 입력·관찰 가능한 성공·실패 차단을 보존하고 각 항목에 구현·GUI/설치 복구·검증 소유자와 최종 gate를 연결한다. 기존 최소 여정을 나중에 정의하겠다는 문서나 일반 체크리스트만으로 완료하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-083',2,'대표 실제 프로젝트·RAW Goal·A/B→C 쓰기/검증·의도된 실패와 재작업 시나리오, worker가 바꿀 수 없는 판정 oracle, artifact bytes/digest/명령 결과·권위 receipt의 대조를 고정한다. fixture 입력과 모델이 생성할 결과를 구분하고 완성 결과/Plan/Task 사전 주입을 금지한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-083',3,'003의 지원 hardware/부하/지속시간에 맞춰 GUI 응답·메모리·사용량 한도를 측정 전에 고정하고 필수 FAIL/NOT_RUN 또는 중대 결함의 출시 차단을 정한다. 001의 역할별 runtime/도구 matrix와 같은 판본에 결속하고 범위·oracle·임계값 변경은 영향·결정·재검증 기록을 요구한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-083',4,'001/031의 공개 접합 계약·085 도구 구현과 082 실제 사전 probe를 준비하고 035 실행 연결→086 candidate governed qualification→044 합성 E2E→059/064 설치본 판정으로 이어지는 개발 계약을 고정한다. M5/M6 선택 기능은 해당 scope 확정 때 실제 release gate 선행으로 추가·검증하며 미선택을 done으로 바꾸지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-084',1,'기존 폴더 열기·새 폴더 생성·프로젝트 전환에 안정된 workspace ID/canonical root/VM project ID와 권한 범위를 연결하고 native/API의 실제 cwd에 적용한다. 샘플 root로 대체하거나 UI 선택만 저장하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-084',2,'단일 root 공유 또는 명시한 projection 방식으로 허용 입력·선행 artifact를 준비하고 동일 bytes/digest/revision을 VM 공개 입력 계약에 결속한다. 후속 Task는 실제 생산 산출물을 읽고 누락/변조/stale 입력은 효과 전에 차단한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-084',3,'한글/공백·경로 정규화·reparse/symlink·허용 root 탈출·다른 workspace 참조를 검증한다. 지원되지 않는 host cwd binding은 실행 불가로 표시하고 더 넓은 OS 격리를 가정하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-084',4,'재시작 뒤 binding을 복원하고 폴더 이동/삭제·접근권한 상실은 구체적 재선택/재결속으로 처리한다. 진행 중 Goal에 대한 전환·입력 변경은 기존 VM revision/인가 규칙을 따르며 별도 Task/입력 권위 원장을 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-085',1,'필수 개발 역할이 실제 workspace에서 read/create/update와 허용된 검증 command를 수행하고 exit code/output·산출물·한도 초과를 반환한다. 도구 목록·인자·cwd·timeout/output 한도를 고정하며 분석 전용 자원과 지원하지 않는 shell 능력을 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-085',2,'VM/AGS 인가·입력 revision·lease·scope를 효과 전에 검증하고 tool_call/effect ID·request digest로 intent/receipt를 연결한다. read-only/idempotent/non-idempotent 효과별 retry·취소·unknown 계약을 기존 VM 권위로 구현하며 새 Task/재시도 엔진을 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-085',3,'결과 재전송은 같은 효과를 다시 실행하지 않고 효과 직후 중단은 실제 상태/receipt 조회 또는 unknown으로 처리한다. 인가 밖 경로·명령·stale 입력을 차단하고 native 실제 권한과 API 제한 도구의 보장 범위를 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-085',4,'실제 파일 bytes/내용과 독립 검증 명령 결과로 성공을 판정한다. 개발 worker가 검증 기준을 바꿔 자기 성공을 만들 수 없고 모델의 설명·가짜 command output·fixture-only 결과로 실제 효과 구현을 완료하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-086',1,'019/033의 고정 test-only candidate route로 실제 검증을 시작하되 사용자 인가·budget/lease·AGS A2/VM gate를 모두 유지한다. 086 PASS 자체를 그 첫 검증 실행의 선행으로 요구하지 않고 성공한 조합만 운영 qualified로 광고한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-086',2,'같은 component manifest/지원 matrix의 모든 필수 runtime/역할에 실제 model/effort·connection·Task/Attempt·pool/lease·provider job·입력 digest를 대조한다. 동일 모델의 다른 계정/host로 묵시 routing되지 않고 재시작 조회/취소도 원래 binding을 사용한다. 필수 미지원/NOT_RUN 또는 upstream 부적합은 완료를 차단한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-086',3,'개발 역할의 실제 파일 생성/수정·한정 검증 command와 API 도구 요청→인가→실행→결과→후속 호출, native 계약을 검증한다. 각 도구의 intent/effect/receipt·결과 반환 경계 crash 및 기본 재시작에서 중복 효과 없음 또는 VM unknown 중단을 실측한다. fixture나 082 probe만으로 운영 적합성을 통과하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-086',4,'역할별 필수 계약 coverage와 대표 합성 목표 044를 구분하고 무한한 vendor×role×복합 Goal 조합을 요구하지 않는다. 060은 이후 설치본 장애 범위를 확장하므로 이 태스크의 선행으로 두지 않는다. 최종 설치본 059/064는 같은 지원 계약과 runtime provenance를 다시 검증한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-087',1,'GUI에서 기존 프로젝트 폴더 선택·새 폴더 생성·전환을 제공하고 현재 workspace/root·연결 사용 범위를 표시한다. CLI 입력이나 번들 샘플 프로젝트만으로 제공하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-087',2,'선택 결과를 084 backend와 VM project/Goal 입력에 결속하고 실제 native/API cwd·생성 파일 위치와 일치함을 검증한다. 다른 workspace 권한을 묵시 공유하거나 실행 중 Goal의 입력/인가 revision을 우회하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-087',3,'재시작 뒤 선택을 복원하고 이동/삭제/접근 불가·지원하지 않는 host root는 이유와 재선택 경로를 제공한다. 한글/공백 경로와 키보드 조작을 설치본 E2E에 포함한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-088',1,'GUI에서 비밀 없는 설정 export/import와 전체 상태 backup/restore를 구분해 시작하고 포함 범위·필요한 재인증·진행/실패/완료 결과를 표시한다. CLI나 소스 checkout을 사용자 절차로 요구하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-088',2,'업데이트 확인/적용·실행 중 worker 처리·실패 복구를 058의 무결성/manifest/소유자 계약으로 연결한다. 앱이 시작되지 않을 때도 설치본과 함께 제공되는 복구 진입점으로 되돌리기/복원을 수행한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-088',3,'새 OS 사용자에서 복원·재인증 후 기존 완료 Goal/근거/실제 파일을 GUI로 열고 active/unknown job을 reconciliation한다. 혼합 checkpoint·누락 파일·취소·부분 실패를 성공으로 꾸미지 않으며 복원 중 중복 효과가 없다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-089',1,'067에서 고정한 기능/route scope와 source commit·새 installer hash·runtime provenance·matrix revision으로 M5 포함 배포물을 만든다. 기본 065/067~075와 선택한 066을 실제 gate 선행으로 등록·검증하고 미선택 기능을 done으로 처리하지 않는다. 필수 연합 route가 하나도 실행되지 않은 상태는 통과하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-089',2,'같은 새 설치본으로 깨끗한 지원 플랫폼 설치와 직전 지원 M4 제품에서 업데이트·중단/일관 복원을 수행하고 P01~P10 회귀를 통과한다. 옛 064 installer의 결과만 재인용하거나 개발 모드 실행으로 패키징 검증을 대체하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-089',3,'두 독립 클러스터에서 P11의 실제 입력 준비·의존 쓰기/검증·재작업·결과 인계·단절/취소/재시작·비밀/권한·비용 흐름을 GUI로 수행한다. 고정 필수 matrix의 FAIL/NOT_RUN·미해결 중대 결함은 출시를 차단하고 선택 unsupported는 지원 주장과 분리한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-089',4,'새 release manifest에 각 여정/조합의 결과·근거 해시·검토자와 서명/무결성·지원/보관/복구 안내를 결속해 배포한다. 이후 M6 변경은 이 PASS를 자동 상속하지 않고 090에서 새 후보로 다시 판정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-090',1,'075에서 고정한 기본 076~079와 선택 확장 scope/matrix에 맞춰 새 commit/installer hash/runtime manifest를 만든다. 080을 선택하면 실제 gate 선행에 추가·검증하고 미선택은 todo/future로 남긴다. 범위 변경은 결정·영향·의존성·재검증 근거 없이 조건을 낮출 수 없다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-090',2,'같은 새 설치본에서 깨끗한 설치·지원 이전 버전에서 업그레이드/일관 복원, P01~P11 회귀와 P12의 각 선언 확장 GUI 등록/역할/실제 작업/근거 인계를 통과한다. adapter fixture나 이전 릴리스 PASS로 해당 판본의 지원을 주장하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-090',3,'각 필수 runtime/역할/도구·조직 경계·선택 배포 환경의 live evidence와 고정 품질/성능 조건을 확인한다. FAIL/NOT_RUN·미해결 중대 결함은 배포를 차단하고 미선택/unsupported 기능은 지원으로 광고하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-090',4,'manifest·릴리스 노트·서명/무결성·지원/운영 가이드를 실제 배포물에 결속해 출시한다. 이 gate의 완료는 선택 scope의 확장 제품 완료이며 장부 전체 90개 완료를 주장하려면 미선택 066/080도 각각 구현/필수 live 기준과 이를 포함한 새 출시 근거를 별도로 충족해야 한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-001',4,'효과 발생 전에 VM의 정확한 Task/Attempt와 AIK route/connection/pool/lease를 결속하는 설치형 공개 extension/dispatch seam, 재시작 lookup/cancel의 동일 계정 routing, 입력·도구 effect intent/receipt 소비자를 명시한다. 현재 seam이 부족하면 upstream 변경/배포물과 AIK-031의 차단 조건으로 추적하며 별도 Task/재시도 원장을 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-001',5,'지원 matrix는 역할별 read/create/update/bounded verification command와 native 실제 권한 범위를 구분한다. 최소 개발 역할은 실제 파일 생성·수정·검증 명령을 제공하며 분석 전용 자원에 동일 shell 능력을 강제하지 않는다. 082는 실제 사전 probe, 086은 구현 후 governed qualification, 044/059는 합성 목표와 GUI 검증으로 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-003',4,'최소/기준 hardware, 지원 파일 경로·오프라인/네트워크 조건, 응답성·메모리·지속 실행의 측정 부하를 결정하고 AIK-083에서 출시 임계값을 측정 전에 고정한다. 실제 provider 지연과 GUI/제어부 응답 시간을 분리하며 미충족 조건은 AIK-062/064를 차단한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-007',4,'설정의 workspace identity와 AIK-084가 결속하는 canonical root/VM project를 참조하며 GUI 선택만 바뀌고 실제 실행 root가 남는 상태를 허용하지 않는다. 설정 export와 전체 제품 상태 백업의 포함 범위·재인증·복구 가능 이력을 구분한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-019',4,'implemented/probe_verified/candidate_for_qualification/qualified를 구분한다. 고정 matrix의 test-only candidate binding은 086 및 같은 계약을 재사용하는 후속 기능 qualification에만 사용하고 기존 인가·한도·AGS A2/VM gate를 모두 적용한다. 해당 조합의 실제 qualification PASS 전에는 일반 운영 inventory/자동 배치에 qualified로 광고하지 않으며 fixture로 qualified live 근거를 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-021',4,'설정 이동은 인증 참조의 재연결과 workspace root 재결속을 요구하며 완료 Goal/근거까지 복구했다고 표시하지 않는다. 전체 상태 복원은 AIK-058 manifest/소유자별 절차를 사용하고 GUI 진입점은 AIK-088에서 제공한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-026',4,'A/B 선행 산출물→후속 C 입력·독립 실패 후 VM 재작업·최종 Goal Test·사용자 결과 인계로 이어지는 제어 흐름과 VM 공개 명령 연결을 구현하고 계약/상태 전이 fixture로 검증한다. 실제 모델·파일·독립 oracle의 합성 목표 완료는 AIK-044/059의 필수 gate에서 검증하며 AIK-026 구현 완료의 선행으로 요구하지 않는다. 총괄이 자체 DAG/재시도/성공 판정 권위를 만들지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-029',4,'각 tool_call/effect identity와 request digest를 Attempt·인가 revision·lease에 결속하고 read-only/idempotent/non-idempotent 효과 종류를 구분한다. 지원 효과의 intent/receipt·unknown·취소 판단은 VM의 공개 권위 계약에 연결하며 gateway 승인을 실제 효과 완료로 기록하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-031',4,'AIK-001에서 정한 실제 runtime 주입점으로 VM 예약·효과 전에 Task/Attempt/인가와 route/connection/pool/lease·workspace 입력을 결속하고 같은 binding으로 inventory·실행·관측·취소를 처리한다. 공개 seam/효과 원장 지원이 부족하면 upstream 선행 변경과 호환 설치물을 확보할 때까지 완료를 차단한다. AIK의 직접 VM SQL 수정이나 별도 재시도 권위로 우회하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-033',4,'일반 실행은 사용할 역할/도구 조합에서 086 또는 같은 계약의 후속 qualification을 실제 통과한 capability만 사용한다. 최초 qualification은 019의 고정 test-only candidate route를 명시적으로 선택해 동일 VM/AGS 인가·A2 gate·budget/lease 검사를 적용한다. qualification PASS를 qualification 실행의 선행으로 요구하는 순환을 만들지 않으며 candidate를 운영 자동 배치에 섞지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-035',4,'VM 예약·효과 경계에서 역할별 route/connection/pool/lease와 canonical cwd·입력 digest를 고정하고 재시작 후 read/cancel도 같은 provider 계정으로 보낸다. 같은 모델명이나 host라는 이유로 다른 연결에 묵시 routing하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-035',5,'AIK-085의 파일 생성/수정·한정 검증 명령을 실제 API/native 개발 경로에 연결한다. tool_call별 효과 전 intent, 효과 후 durable receipt와 모델 결과 반환을 구분하고 같은 결과 재전송은 재실행 없이 처리한다. 미확정 효과·취소 경쟁은 VM unknown/reconciliation을 따르며 provider job 완료를 모든 도구 효과 완료로 간주하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-037',4,'최종 산출물은 worker/임시 세션 반환 뒤에도 약속한 보관 범위에서 접근 가능한 사용자 프로젝트 또는 관리 저장소에 인계하고 GUI 열기·저장/내보내기와 재시작 뒤 bytes/digest를 검증한다. 선행 산출물의 후속 Task 입력 binding은 AIK-084와 VM 공개 참조 계약을 사용하고 파일명만으로 최신성을 추정하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-038',4,'실행 중인 개별 도구 효과와 늦은 receipt도 취소/회수 절차에 포함하고 결과 인계·필수 근거의 durable 보관이 확인되기 전에 임시 worker 데이터를 제거하지 않는다. 불명확한 효과를 숨겨 lease 회수만으로 정상 완료 처리하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-039',4,'모델 job뿐 아니라 tool_call/effect intent/receipt를 조회해 결과 재전송과 효과 재실행을 구분한다. 효과 직후 receipt 전 crash, receipt 후 모델 응답 전 crash, 취소 뒤 늦은 효과에서 중복을 막고 원래 route/계정으로 회복한다. 비멱등 효과가 불명확하면 확인 또는 기존 VM의 구체적 판단 절차까지 중단하며 임의 exactly-once를 주장하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-042',4,'개발 worker가 만든 파일을 독립 검사자가 실제 한정 검증 명령과 고정 판정 기준으로 검사한다. 의도된 실패 뒤 기존 VM 재작업/Goal Test를 거쳐 수정된 실제 bytes와 근거로만 성공을 보고하며 worker의 테스트 기준 임의 변경이나 자기선언으로 통과하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-050',4,'AIK-087에서 선택한 실제 workspace를 Goal에 결속해 표시하고 실행 중 후속 정정을 같은 Goal의 올바른 revision/인가 변경에 연결한다. 기존 인가를 반복 질문하지 않되 새 revision의 변경 범위는 VM 규칙대로 처리하며 다른 프로젝트나 새 중복 Goal로 묵시 전환하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-054',4,'사용자 동작으로 최종 파일 열기와 저장/내보내기를 제공하고 내보낸 실제 bytes/digest를 원본 또는 명시한 표시용 derivative와 대조한다. worker 반환과 앱 재시작 뒤에도 약속한 보관 범위의 결과를 사용하며 외부 파일 변경·보관 만료·접근 실패를 정확히 표시한다. 콘텐츠 표시만으로 파일/명령을 자동 실행하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-058',4,'설정-only export와 전체 제품 상태 백업을 구분한다. AIK 설정/참조, VM Goal/Attempt, AGS evidence, 실제 artifact를 각 소유자의 공개 checkpoint·정지/재개·복원 절차로 같은 복구 지점에 결속하고 공통 manifest에 schema/runtime 버전·시점·hash·참조 무결성·외부 job identity를 기록한다. 동작 중 DB 파일의 임의 복사로 일관성을 주장하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-058',5,'서로 다른 checkpoint·누락/변조 artifact·호환 불가 version은 복원 성공을 차단한다. 복원 뒤 완료 Goal/검토/실제 결과가 열리고 진행 중/unknown job은 기존 provider와 VM reconciliation으로 처리해 자동 중복 효과를 막는다. 새 사용자 비밀은 재인증하며 AIK-088이 소비할 공개 backend 계약을 제공하며 GUI/설치 복구 화면의 실제 검증은 088/059에서 수행한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-060',4,'실제 파일 변경 도구의 intent 전/후, effect 후 receipt 전, receipt 후 모델 결과 반환 전 각각에서 crash·취소·늦은 결과를 주입한다. 파일 내용/효과 횟수와 VM intent/receipt로 중복 없음 또는 명시적 unknown 중단을 판정하며 provider job만의 중복 방지로 대체하지 않는다. 086의 기본 경계를 설치본에서 재검증하고 네트워크/인증/한도 장애로 확장한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-062',4,'003/083에서 측정 전에 고정한 지원 hardware·프로젝트/작업 수·부하·지속시간·GUI 응답/메모리/사용량 한도를 같은 installer/matrix로 검증한다. provider 지연과 UI/제어부 응답을 분리하고 기준 미충족은 064를 차단한다. 측정 뒤 기준을 낮추거나 병렬 미지원 경로의 가상 수치를 사용하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-063',4,'사용자 프로젝트 열기/이동, 지원 개발 도구/검증 범위, 결과 보관/내보내기, 설정-only와 전체 백업 차이, 앱 부팅 실패 시 복구 진입점을 설치본에서 그대로 따라 할 수 있게 안내한다. 미완료 후속 기능을 첫 출시 설치본의 지원으로 표시하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-064',4,'release manifest는 P01~P10별 시나리오·지원 조합·실제 실행 결과·근거 위치/해시·검토자를 포함한다. 이 gate는 M0~M4 첫 제품(Windows·Linux)을 판정하며 M5 연합과 M6 확장의 출시 완료는 각각 089/090의 새로운 배포 후보로 판정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-066',4,'출시에 선택한 Cloud 생성 경로는 adapter 구현과 실제 생성/재연결/실행/결과/회수 근거를 기능 후보 패키지에서 확보하고 089의 새 배포 후보에서 다시 검증한다. unsupported 결과만으로 선택 기능의 구현/지원 완료를 주장하지 않는다. 미선택 경로는 기본 연합 출시를 막지 않고 선택 시 실제 gate 선행으로 추가한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-067',4,'M5 기본 출시 범위는 실제 두 클러스터 연합과 065/067~075이며 지원 route를 모두 미검증으로 두고 완료할 수 없다. 066의 Cloud 생성은 별도 선택으로 release scope/matrix를 구현 전에 고정하고 선택 시 089의 실제 선행으로 추가한다. 위임된 파일 쓰기/검증·후속 입력·effect receipt와 원격 불명확 효과 복구 계약도 버전으로 명시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-071',4,'수신 worker의 실제 파일 생성/수정·검증 명령 결과와 effect identity/receipt를 회수하고 그 산출물을 허용된 후속 Task 입력에 결속한다. sender logical path와 receiver projection의 결과 반환 경로를 구분하며 재전송/단절 뒤 불명확한 쓰기 효과를 자동 중복 실행하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-072',4,'원격 변경 산출물의 실제 bytes/digest와 effect receipt를 인계하고 sender가 GUI로 열기/저장하거나 후속 Task 입력으로 소비할 수 있게 한다. 원격 lease/worker 반환 뒤에도 약속한 보관 범위에서 접근 가능하며 단순 ACK나 존재하지 않는 원격 경로를 결과 인계로 취급하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-074',4,'사전 수동 복제 없이 준비한 입력으로 원격 worker가 파일 생성/수정·한정 검증을 실제 수행하고 반환된 산출물을 후속 Task가 소비한다. 독립 실패 후 재작업, 단절된 쓰기 효과의 unknown/receipt 회복, sender GUI의 결과 열기/저장을 확인한다. 읽기 전용 독립 Task만으로 P11을 통과하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-075',4,'089의 새 설치본·업그레이드·첫 출시 회귀에서 실행할 연합 사용자 시나리오와 기능 후보 패키지를 제공한다. 다음 M6 판본의 기본 076~079와 선택 080 지원 범위를 실제 확장 qualification 전에 고정하고 선택한 080은 090의 선행에 추가한다. 미선택 기능은 todo/future로 유지하며 scope 변경은 결정·영향·검증을 기록한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-076',4,'057의 빌드 절차를 재사용한 기능 후보 설치본에서 로컬 개발 역할의 실제 workspace 입력·쓰기/검증·결과 인계와 설치/업그레이드 회귀를 검증하고 090의 통합 출시 검증에 제공한다. 역할이 분석 전용이면 capability로 제한하고 로컬 개발 역할 지원을 fixture나 텍스트 응답만으로 주장하지 않는다. 090의 최종 PASS는 이 기능 구현의 선행이 아니다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-077',4,'새 adapter 예시를 057 빌드 절차의 기능 후보 설치본에서 선언한 역할/도구 효과·취소/복구·입력/결과 계약으로 실제 검증하고 090에 제공한다. SDK 단위 conformance와 배포물 포함·GUI 실행의 근거를 구분하며 090의 최종 PASS를 선행으로 요구하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-078',4,'057 빌드 절차의 기능 후보 설치본 GUI에서 정책 적용 전/후 실제 같은 목표·역할 binding·품질/비용 근거와 업그레이드 후 schema/revision 보존을 확인해 090에 제공한다. 090의 최종 PASS를 이 기능 완료의 선행으로 요구하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-079',4,'057 빌드 절차의 기능 후보 설치본 GUI에서 서로 다른 조직 identity로 위임 허용/거부·권한 회수·결과 접근과 실제 원격 효과/근거 및 업그레이드 이후 권한 경계를 검증해 090에 제공한다. 090의 최종 PASS를 선행으로 요구하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-080',4,'선택한 경우 090의 선행으로 등록하고 057 빌드 절차의 기능 후보 설치본에서 GUI 장착·별도 Kubernetes support contract의 실제 생성/관측/drain/결과/회수·실행 근거와 실패 복구를 검증해 090에 제공한다. 미지원 관측은 구분하며 다른 Cloud 경로 성공을 Kubernetes 성공으로 대체하지 않는다. 미선택이면 todo/future를 유지하고 Kubernetes 지원이나 전체 로드맵 완료로 표시하지 않는다. 066의 Cloud API 지원이나 090 최종 PASS를 이 기능의 선행으로 요구하지 않는다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-091',1,'공통 코드의 os.name·sys.platform 분기가 플랫폼 계층 한 곳으로 모이고, 각 concern은 좁은 port로 주입·대체할 수 있다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-091',2,'기존 공개 이름·파일 권한(mode)·오류 코드·잠금 의미가 바뀌지 않음을 기존 전체 회귀가 Windows·Linux CI에서 확인한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-091',3,'Linux adapter는 거절(fail-closed) 경로를 포함해 실제 Linux에서 검증하고, 미구현 concern은 거절 사유와 함께 표시한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-092',1,'aik_adapter_*·aik_host_* 밖의 공통 패키지가 벤더 adapter 모듈을 import하지 않음을 시험으로 고정한다.');
INSERT INTO "acceptance_criteria" VALUES('AIK-092',2,'새 벤더 adapter는 공통 코드 수정 없이 등록만으로 진단·선택 대상이 된다.');
INSERT INTO "change_log" VALUES(1,'metadata','schema_version','value','1','2','schema v1 -> v2 migration by tools/backlog.py migrate; every v1 row is copied unchanged','2026-10-14T01:54:45Z','','7fa580940bf174bf147559d028c9fc4a05e06bd49924618bcbb9aea4b3c88cc0');
INSERT INTO "change_log" VALUES(2,'source','S-USER-20261014','created',NULL,'S-USER-20261014 · 사용자 설계 원칙: 벤더 독립·OS 독립·SOLID와 첫 출시 Windows·Linux · user · 2026-10-14 · 사용자 원문: "나의 철학은 1. 밴더 독립은 무조건 지킨다 2. 운영체제에도 독립적이어야한다 3. SOLID 원칙을 좋아한다". 출시 OS는 Windows·Linux 둘 다(진행은 Windows 우선), Linux 비밀 저장은 Secret Service, 원장은 스키마까지 개편.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','7fa580940bf174bf147559d028c9fc4a05e06bd49924618bcbb9aea4b3c88cc0','75ea13a4cfd2c6038a4c35e1b1f713bb9240ba389e6aafb512555678d89b9d53');
INSERT INTO "change_log" VALUES(3,'principle','PRN-VENDOR','created',NULL,'PRN-VENDOR · 벤더 독립 · 벤더 독립은 무조건 지킨다. 공통 계약·저장소·GUI는 특정 벤더를 모르고, 벤더 차이는 adapter에만 둔다. 공통 코드는 벤더 adapter 모듈을 import하지 않는다. · S-USER-20261014','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','75ea13a4cfd2c6038a4c35e1b1f713bb9240ba389e6aafb512555678d89b9d53','1953cf630c24619164de822901e3cf96899310cb541e9ea251715b8a74b54936');
INSERT INTO "change_log" VALUES(4,'principle','PRN-OS','created',NULL,'PRN-OS · 운영체제 독립 · 공통 코드는 운영체제를 모른다. 파일·잠금·프로세스·경로·시크릿·세션 신호의 OS 차이는 port 뒤 플랫폼 adapter에만 두고, OS 판별은 플랫폼 계층 한 곳에서만 한다. · S-USER-20261014','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','1953cf630c24619164de822901e3cf96899310cb541e9ea251715b8a74b54936','82c3be6ad7901a6d66c18c8b4d99d599675151a28433d5f5e2e48c9d478996bb');
INSERT INTO "change_log" VALUES(5,'principle','PRN-SOLID','created',NULL,'PRN-SOLID · SOLID · 단일 책임과 좁은 인터페이스(ISP), 추상에 대한 의존(DIP)을 지키고, 새 OS·벤더는 기존 코드 수정이 아니라 adapter 추가로 지원한다(OCP). · S-USER-20261014','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','82c3be6ad7901a6d66c18c8b4d99d599675151a28433d5f5e2e48c9d478996bb','75a593ca695673850129d7cc73fc5dcdbbf9382b4ab46ba697bd0e98950c3336');
INSERT INTO "change_log" VALUES(6,'platform','WIN-X64','created',NULL,'WIN-X64 · Windows x64 · windows · first_release · 지원 버전·설치 형식은 DEC08/AIK-003. 진행 우선 플랫폼.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','75a593ca695673850129d7cc73fc5dcdbbf9382b4ab46ba697bd0e98950c3336','1fbd24ebe9b41f7722e96be6b1043fbcc2b43def689de5ba7d5029ceffca53f4');
INSERT INTO "change_log" VALUES(7,'platform','LINUX-X64','created',NULL,'LINUX-X64 · Linux x64 · linux · first_release · 지원 배포판·설치 형식은 미정(DEC08/AIK-003). VM 실행 의존 부분은 EXT-VM-POSIX-D1 외부 선행.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','1fbd24ebe9b41f7722e96be6b1043fbcc2b43def689de5ba7d5029ceffca53f4','c66c8f5e5eadb790eb3a8d9fe4e4cbd59542d177f848a390a4179036000b291e');
INSERT INTO "change_log" VALUES(8,'external_dependency','EXT-VM-POSIX-D1','created',NULL,'EXT-VM-POSIX-D1 · vm · VibeMarshal RuntimeJob owner lock의 POSIX 지원 · open · vibemarshal src/flowmarshal/engine/runtime.py (os.name == ''nt'', msvcrt 잠금; POSIX는 fail-closed, VM 결정 D1) · VM은 수정하지 않는 고정 계약이다. VM이 POSIX 잠금을 지원할 때까지 Linux에서 VM 실제 실행에 의존하는 플랫폼 행은 완료할 수 없다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','c66c8f5e5eadb790eb3a8d9fe4e4cbd59542d177f848a390a4179036000b291e','8b7a37ca0a5fe2db84c626bca0c72d200f371c5944700daf426d3391c54108e2');
INSERT INTO "change_log" VALUES(9,'external_dependency','EXT-AGS-A2-HOSTINTEGRATION','created',NULL,'EXT-AGS-A2-HOSTINTEGRATION · ags · AGS host-integration.json(HostIntegration.v1)과 A2 profile의 main 반영 · open · agent-governance-suite main 2.9.0(56fef8bd)에 없음; 리뷰 후보 codex/v260-semantic-decision-layer · AGS는 수정하지 않는 고정 계약이다. 반영 전에는 실제 A2 적합성 PASS가 불가능하다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','8b7a37ca0a5fe2db84c626bca0c72d200f371c5944700daf426d3391c54108e2','0e04818efa827d4510af89ac1fd074f0be8fe77b0bfe4070a14f4d1976d11e6b');
INSERT INTO "change_log" VALUES(10,'requirement','U04','title','첫 출시 Windows 전용','첫 출시 Windows·Linux','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','0e04818efa827d4510af89ac1fd074f0be8fe77b0bfe4070a14f4d1976d11e6b','246439774a0350c1eaaa8ffce3920f62a464c658ffb6797be12e97431569b828');
INSERT INTO "change_log" VALUES(11,'requirement','U04','description','첫 제품 배포와 완료조건은 Windows를 대상으로 한다. 다른 OS 출시를 선행조건으로 두지 않는다.','첫 제품 배포와 완료조건은 지원 플랫폼 Windows x64와 Linux x64를 대상으로 한다. 진행은 Windows를 먼저 하고, Linux에서 VM 실행에 의존하는 부분은 VM POSIX 지원(외부 선행 EXT-VM-POSIX-D1)이 해소될 때까지 차단으로 둔다. macOS 출시는 선행조건으로 두지 않는다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','246439774a0350c1eaaa8ffce3920f62a464c658ffb6797be12e97431569b828','b495e377fee17a10ffb9cdca4c7c222429e98445d02e52b71ac398212ca3c1f4');
INSERT INTO "change_log" VALUES(12,'requirement','U10','created',NULL,'U10 · user · OS 독립 구조 · 공통 코드는 운영체제를 모른다. 파일·잠금·프로세스·경로·시크릿·세션 신호 같은 OS 차이는 port 뒤 플랫폼 adapter에만 두고, 새 OS 지원은 adapter 추가로 한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','b495e377fee17a10ffb9cdca4c7c222429e98445d02e52b71ac398212ca3c1f4','1e7e402c9d84cebde84dd4e78005844f8d2bce4ee9987029652b58ff890eb918');
INSERT INTO "change_log" VALUES(13,'requirement','U11','created',NULL,'U11 · user · 벤더 독립 구조 · 공통 계약·저장소·GUI는 특정 벤더를 모른다. 벤더 차이는 adapter에만 두고 공통 코드는 벤더 adapter 모듈을 import하거나 벤더 목록을 하드코딩하지 않는다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','1e7e402c9d84cebde84dd4e78005844f8d2bce4ee9987029652b58ff890eb918','7d77fb81af20f6e043698f1bdc61893e015ac408a26f8847d5f69613a9e42ca1');
INSERT INTO "change_log" VALUES(14,'requirement','D01','description','실비밀은 Windows 사용자 vault 또는 공식 호스트 저장소에 둔다. 프롬프트·장부·PEER·로그에는 참조와 비민감 metadata만 사용한다.','실비밀은 OS 사용자 범위 vault(Windows DPAPI·Linux Secret Service) 또는 공식 호스트 저장소에 둔다. 프롬프트·장부·PEER·로그에는 참조와 비민감 metadata만 사용한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','7d77fb81af20f6e043698f1bdc61893e015ac408a26f8847d5f69613a9e42ca1','1e64b8bb70e27425566a52555dcb5ef709c43fdbfea304263bfc1384f4b747f5');
INSERT INTO "change_log" VALUES(15,'requirement','D07','title','Windows 운영성과 배포 품질','플랫폼 운영성과 배포 품질','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','1e64b8bb70e27425566a52555dcb5ef709c43fdbfea304263bfc1384f4b747f5','d1a4989cfbb67455f9060eb51f0ddb75a9b4dc7d2e84aee3836a8261736a815c');
INSERT INTO "change_log" VALUES(16,'requirement','D07','description','설치·업데이트·한글 UI·접근성·실패 복구·진단 및 동작 측정을 첫 출시 범위로 검증한다.','설치·업데이트·한글 UI·접근성·실패 복구·진단 및 동작 측정을 첫 출시 지원 플랫폼마다 검증한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','d1a4989cfbb67455f9060eb51f0ddb75a9b4dc7d2e84aee3836a8261736a815c','30c4bd16c953bb064a5eec25913cb7315c5465eb8cf9f22f23fd2441272e1227');
INSERT INTO "change_log" VALUES(17,'requirement','P01','description','범위: 첫 Windows 출시. 시나리오: 개발 도구 없는 지원 Windows에 설치하고 GUI에서 두 벤더의 필수 API/지원 구독 경로를 연결한 뒤 만료·재인증·계정 교체·해제를 수행한다. 통과: 고정 matrix의 실제 계정/connection binding과 인증 상태가 일치하고 교체 후 다음 실행이 선택 계정으로 전달된다. 차단: 필수 경로 미지원/NOT_RUN, 외부 로그인 변경의 묵시 계정 전환, fixture만의 성공, 수동 CLI 사전 설정. 선택 경로의 unsupported는 별도 표시한다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 개발 도구 없는 지원 Windows에 설치하고 GUI에서 두 벤더의 필수 API/지원 구독 경로를 연결한 뒤 만료·재인증·계정 교체·해제를 수행한다. 통과: 고정 matrix의 실제 계정/connection binding과 인증 상태가 일치하고 교체 후 다음 실행이 선택 계정으로 전달된다. 차단: 필수 경로 미지원/NOT_RUN, 외부 로그인 변경의 묵시 계정 전환, fixture만의 성공, 수동 CLI 사전 설정. 선택 경로의 unsupported는 별도 표시한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','30c4bd16c953bb064a5eec25913cb7315c5465eb8cf9f22f23fd2441272e1227','d19e1446338fd010036c8605c78c060323bb6ca983bc58215f7d72fdba2a9ce9');
INSERT INTO "change_log" VALUES(18,'requirement','P02','description','범위: 첫 Windows 출시. 시나리오: GUI에서 기존 한글/공백 경로 프로젝트를 열고 새 폴더를 만들며 다른 프로젝트로 전환한다. 통과: 화면 workspace, VM project/root, native/API cwd, 허용 입력·선행 산출물의 bytes/digest/revision이 실제 실행과 일치하고 재시작 뒤 유지된다. 차단: 샘플 root 대체, 다른 workspace 쓰기, 누락/변조/stale 입력, 허용 root를 벗어난 경로 또는 해석 불가 참조. 이동·권한 상실은 안내와 재결속 절차로 처리한다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: GUI에서 기존 한글/공백 경로 프로젝트를 열고 새 폴더를 만들며 다른 프로젝트로 전환한다. 통과: 화면 workspace, VM project/root, native/API cwd, 허용 입력·선행 산출물의 bytes/digest/revision이 실제 실행과 일치하고 재시작 뒤 유지된다. 차단: 샘플 root 대체, 다른 workspace 쓰기, 누락/변조/stale 입력, 허용 root를 벗어난 경로 또는 해석 불가 참조. 이동·권한 상실은 안내와 재결속 절차로 처리한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','d19e1446338fd010036c8605c78c060323bb6ca983bc58215f7d72fdba2a9ce9','ca1115113fbb322c41390e82c3aa2544741f3219fe0f5bd67ce9467c0629a0ab');
INSERT INTO "change_log" VALUES(19,'requirement','P03','description','범위: 첫 Windows 출시. 시나리오: GUI에서 총괄과 개발/검토 역할에 서로 다른 connection/model/지원 effort를 지정하고 실제 목표를 수행한다. 통과: 역할별 요청값과 provider 관측값, Attempt/lease/job/계정 binding이 근거로 대조되며 허용 fallback만 적용된다. 차단: 설정값을 실측으로 표시, 다른 계정/모델로 묵시 routing, 미관측 필드의 추정, 운영 미검증 자원의 qualified 광고. 읽기 전용 분석 역할과 파일/검증 도구를 가진 개발 역할의 지원 능력을 구분한다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: GUI에서 총괄과 개발/검토 역할에 서로 다른 connection/model/지원 effort를 지정하고 실제 목표를 수행한다. 통과: 역할별 요청값과 provider 관측값, Attempt/lease/job/계정 binding이 근거로 대조되며 허용 fallback만 적용된다. 차단: 설정값을 실측으로 표시, 다른 계정/모델로 묵시 routing, 미관측 필드의 추정, 운영 미검증 자원의 qualified 광고. 읽기 전용 분석 역할과 파일/검증 도구를 가진 개발 역할의 지원 능력을 구분한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','ca1115113fbb322c41390e82c3aa2544741f3219fe0f5bd67ce9467c0629a0ab','e4717b96a99a04f90780d9d368a5fd805f1c06993b7d472a7936af53b6e90631');
INSERT INTO "change_log" VALUES(20,'requirement','P04','description','범위: 첫 Windows 출시. 시나리오: 사용자가 고른 프로젝트에 RAW Goal 하나를 제출하고 실제 총괄/VM 준비 경로가 A·B 독립 작업과 두 결과를 소비하는 C를 구성한다. 두 벤더 자원이 실제 파일을 생성/수정하고 한정된 검증 명령을 실행한다. 통과: 독립 검사에 의도적으로 한 번 실패한 뒤 기존 인가·VM 재작업 절차로 수정해 최종 Goal Test와 사용 가능한 산출물을 얻는다. 후속 정정도 같은 Goal의 올바른 revision에 반영한다. 차단: 미리 넣은 Plan/Task/완성 출력, 후속 입력 미전달, 검사 생략·기준 임의 수정, 모델 자기선언만의 성공, stale 인가. VM 직렬 기본과 qualification된 병렬 범위를 유지한다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 사용자가 고른 프로젝트에 RAW Goal 하나를 제출하고 실제 총괄/VM 준비 경로가 A·B 독립 작업과 두 결과를 소비하는 C를 구성한다. 두 벤더 자원이 실제 파일을 생성/수정하고 한정된 검증 명령을 실행한다. 통과: 독립 검사에 의도적으로 한 번 실패한 뒤 기존 인가·VM 재작업 절차로 수정해 최종 Goal Test와 사용 가능한 산출물을 얻는다. 후속 정정도 같은 Goal의 올바른 revision에 반영한다. 차단: 미리 넣은 Plan/Task/완성 출력, 후속 입력 미전달, 검사 생략·기준 임의 수정, 모델 자기선언만의 성공, stale 인가. VM 직렬 기본과 qualification된 병렬 범위를 유지한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','e4717b96a99a04f90780d9d368a5fd805f1c06993b7d472a7936af53b6e90631','b73445d3c23f8d0df8e6a23fa67ca80ea3ccb4ad4801e5d92baf9be1b9872765');
INSERT INTO "change_log" VALUES(21,'requirement','P05','description','범위: 첫 Windows 출시. 시나리오: 허용된 프로젝트 작업을 실행하고 범위 확대·다른 workspace·예산/동시성 한도·만료 인증을 각각 시도한다. 통과: 기존 인가는 반복 질문 없이 전달되고 확대 또는 stale 요청만 기존 VM/AGS 절차로 중단되며 GUI가 구체 이유와 다음 행동을 표시한다. 합성 비밀을 이용해 prompt/로그/IPC/근거/지원 번들 노출과 실제 OS trust profile을 검사한다. 차단: 우회 도구 실행, 권한 자가 부여, 무제한/0으로 꾸민 unknown usage, 실제보다 강한 native 격리 주장.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 허용된 프로젝트 작업을 실행하고 범위 확대·다른 workspace·예산/동시성 한도·만료 인증을 각각 시도한다. 통과: 기존 인가는 반복 질문 없이 전달되고 확대 또는 stale 요청만 기존 VM/AGS 절차로 중단되며 GUI가 구체 이유와 다음 행동을 표시한다. 합성 비밀을 이용해 prompt/로그/IPC/근거/지원 번들 노출과 실제 OS trust profile을 검사한다. 차단: 우회 도구 실행, 권한 자가 부여, 무제한/0으로 꾸민 unknown usage, 실제보다 강한 native 격리 주장.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','b73445d3c23f8d0df8e6a23fa67ca80ea3ccb4ad4801e5d92baf9be1b9872765','f7ef798f2af17ec7bf99ac4291e9e907b5c40d8f6f6eaa93d4950cac38658115');
INSERT INTO "change_log" VALUES(22,'requirement','P06','description','범위: 첫 Windows 출시. 시나리오: 실제 임시 프로젝트 파일 변경에서 effect 전 intent, effect 후 receipt, 모델에 도구 결과를 반환하는 각 경계에 중단·취소·늦은 결과를 주입한다. 통과: tool_call/effect identity와 request digest가 Attempt/인가/lease에 연결되고 같은 효과가 중복되지 않으며 기존 결과 재전송 또는 VM unknown/reconciliation으로 수렴한다. 차단: provider job 조회만으로 도구 효과 성공을 추정하거나 불명확한 비멱등 효과를 자동 재실행. 임의 외부 명령에 exactly-once를 주장하지 않는다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 실제 임시 프로젝트 파일 변경에서 effect 전 intent, effect 후 receipt, 모델에 도구 결과를 반환하는 각 경계에 중단·취소·늦은 결과를 주입한다. 통과: tool_call/effect identity와 request digest가 Attempt/인가/lease에 연결되고 같은 효과가 중복되지 않으며 기존 결과 재전송 또는 VM unknown/reconciliation으로 수렴한다. 차단: provider job 조회만으로 도구 효과 성공을 추정하거나 불명확한 비멱등 효과를 자동 재실행. 임의 외부 명령에 exactly-once를 주장하지 않는다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','f7ef798f2af17ec7bf99ac4291e9e907b5c40d8f6f6eaa93d4950cac38658115','7d45554ecb2f5ccd3be64f47ba5ede625755fc6e710da27b3c48e2e402c67561');
INSERT INTO "change_log" VALUES(23,'requirement','P07','description','범위: 첫 Windows 출시. 시나리오: 합성 목표의 최종 파일·검증 근거를 GUI에서 열고 저장/내보낸 뒤 worker 반환과 앱 재시작 후 다시 사용한다. 통과: 사용자가 받은 bytes/digest와 VM verdict의 산출물/검토 근거가 일치하고 약속한 보관 범위에서 유지되며 후속 Task 입력도 같은 권위 참조에 결속된다. 차단: 종료된 임시 worker 경로만 제공, 깨진 다운로드, 표시용 derivative를 원본 근거로 대체, unsafe 결과 콘텐츠의 자동 실행. 보관 만료·외부 파일 변경은 명확히 표시한다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 합성 목표의 최종 파일·검증 근거를 GUI에서 열고 저장/내보낸 뒤 worker 반환과 앱 재시작 후 다시 사용한다. 통과: 사용자가 받은 bytes/digest와 VM verdict의 산출물/검토 근거가 일치하고 약속한 보관 범위에서 유지되며 후속 Task 입력도 같은 권위 참조에 결속된다. 차단: 종료된 임시 worker 경로만 제공, 깨진 다운로드, 표시용 derivative를 원본 근거로 대체, unsafe 결과 콘텐츠의 자동 실행. 보관 만료·외부 파일 변경은 명확히 표시한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','7d45554ecb2f5ccd3be64f47ba5ede625755fc6e710da27b3c48e2e402c67561','47b4ac5c6a102f1cb344f1112c7754184e5d885af09d3bdcc4a725bbf225a65d');
INSERT INTO "change_log" VALUES(24,'requirement','P08','description','범위: 첫 Windows 출시. 시나리오: 목표 실행 중 창 닫기/재열기, 앱/sidecar 재시작, 일시정지·재개·취소를 수행한다. 통과: 같은 Goal·대화·미처리 지시·진행 job·인가 revision을 복원하고 requested/observed 모델·상태·usage·unknown 이유를 조회한다. 신규 배치 중지와 실제 종료를 구분하며 자체 worker만 종료하고 borrowed host는 lease를 반환한다. 차단: 새 Goal 중복 생성, 미처리 지시 유실, 유휴 무한 모델 호출, 회수되지 않는 lease 또는 사용자 호스트 강제 종료.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 목표 실행 중 창 닫기/재열기, 앱/sidecar 재시작, 일시정지·재개·취소를 수행한다. 통과: 같은 Goal·대화·미처리 지시·진행 job·인가 revision을 복원하고 requested/observed 모델·상태·usage·unknown 이유를 조회한다. 신규 배치 중지와 실제 종료를 구분하며 자체 worker만 종료하고 borrowed host는 lease를 반환한다. 차단: 새 Goal 중복 생성, 미처리 지시 유실, 유휴 무한 모델 호출, 회수되지 않는 lease 또는 사용자 호스트 강제 종료.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','47b4ac5c6a102f1cb344f1112c7754184e5d885af09d3bdcc4a725bbf225a65d','b5fba545b9f57e1213c44899480104d6d6e5287ffb821a8ad232602f1aa65862');
INSERT INTO "change_log" VALUES(25,'requirement','P09','description','범위: 첫 Windows 출시. 시나리오: GUI에서 비밀 없는 설정 이동과 제품 상태 백업을 구분해 수행하고, 업데이트 중단 또는 새 Windows 사용자에서 설치본의 복구 화면으로 복원·재인증한다. 통과: AIK 설정, VM Goal/Attempt, AGS 근거, 실제 artifact가 각 소유자의 공개 checkpoint/복원 절차와 공통 manifest로 같은 복구 지점에 맞고 완료 이력이 열린다. 실행 중/unknown 외부 job은 조회·reconciliation 후 처리한다. 차단: 서로 다른 시점의 DB를 참조 문자열만 맞춰 성공 처리, dangling evidence, 자동 중복 효과, CLI/소스 checkout 필수. 앱 부팅 실패 때도 제공되는 복구 진입점이 있다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: GUI에서 비밀 없는 설정 이동과 제품 상태 백업을 구분해 수행하고, 업데이트 중단 또는 새 Windows 사용자에서 설치본의 복구 화면으로 복원·재인증한다. 통과: AIK 설정, VM Goal/Attempt, AGS 근거, 실제 artifact가 각 소유자의 공개 checkpoint/복원 절차와 공통 manifest로 같은 복구 지점에 맞고 완료 이력이 열린다. 실행 중/unknown 외부 job은 조회·reconciliation 후 처리한다. 차단: 서로 다른 시점의 DB를 참조 문자열만 맞춰 성공 처리, dangling evidence, 자동 중복 효과, CLI/소스 checkout 필수. 앱 부팅 실패 때도 제공되는 복구 진입점이 있다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','b5fba545b9f57e1213c44899480104d6d6e5287ffb821a8ad232602f1aa65862','48ec740c6bf0565deba71130b583570986cddb3cd988a3a1ba26debd629e8421');
INSERT INTO "change_log" VALUES(26,'requirement','P10','description','범위: 첫 Windows 출시. 시나리오: 하나의 commit/installer hash·runtime manifest·지원 matrix 판본에 P01~P09, 깨끗한 설치/제거, 한글/키보드/접근성, 장애·비밀·성능·지원 안내 검증을 연결한다. 통과: AIK-003/083에서 측정 전에 고정한 hardware/부하/지속시간과 응답·메모리·사용량 한도에 대한 독립 결과가 충족되고 release notes/지원 주장과 일치한다. 차단: 필수 FAIL/NOT_RUN/미해결 중대 결함, 다른 빌드의 혼합 근거, 사후 임계값 완화, 개발 환경만의 성공. 우선순위 P1도 첫 출시 범위이면 필수다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 하나의 commit/installer hash·runtime manifest·지원 matrix 판본에 P01~P09, 깨끗한 설치/제거, 한글/키보드/접근성, 장애·비밀·성능·지원 안내 검증을 연결한다. 통과: AIK-003/083에서 측정 전에 고정한 hardware/부하/지속시간과 응답·메모리·사용량 한도에 대한 독립 결과가 충족되고 release notes/지원 주장과 일치한다. 차단: 필수 FAIL/NOT_RUN/미해결 중대 결함, 다른 빌드의 혼합 근거, 사후 임계값 완화, 개발 환경만의 성공. 우선순위 P1도 첫 출시 범위이면 필수다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','48ec740c6bf0565deba71130b583570986cddb3cd988a3a1ba26debd629e8421','b9ac32a125697b98daba888f0c54516a8e84fc9c7f0a13cbca89b57df79d4bf3');
INSERT INTO "change_log" VALUES(27,'requirement','P01','description','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 개발 도구 없는 지원 Windows에 설치하고 GUI에서 두 벤더의 필수 API/지원 구독 경로를 연결한 뒤 만료·재인증·계정 교체·해제를 수행한다. 통과: 고정 matrix의 실제 계정/connection binding과 인증 상태가 일치하고 교체 후 다음 실행이 선택 계정으로 전달된다. 차단: 필수 경로 미지원/NOT_RUN, 외부 로그인 변경의 묵시 계정 전환, fixture만의 성공, 수동 CLI 사전 설정. 선택 경로의 unsupported는 별도 표시한다.','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 개발 도구 없는 지원 플랫폼에 설치하고 GUI에서 두 벤더의 필수 API/지원 구독 경로를 연결한 뒤 만료·재인증·계정 교체·해제를 수행한다. 통과: 고정 matrix의 실제 계정/connection binding과 인증 상태가 일치하고 교체 후 다음 실행이 선택 계정으로 전달된다. 차단: 필수 경로 미지원/NOT_RUN, 외부 로그인 변경의 묵시 계정 전환, fixture만의 성공, 수동 CLI 사전 설정. 선택 경로의 unsupported는 별도 표시한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','b9ac32a125697b98daba888f0c54516a8e84fc9c7f0a13cbca89b57df79d4bf3','2aeb8e8979af4213804892d45c13ff4239d83c29222cd5e577192b5cc65b31db');
