INSERT INTO "change_log" VALUES(49,'milestone','M3','exit_criteria','사용자 프로젝트 선택부터 인증·총괄/worker 모델 지정·RAW Goal/정정·실제 개발 작업·결과 사용·중단/재접속까지 GUI로 수행한다.','사용자 프로젝트 선택부터 인증·총괄/worker 모델 지정·RAW Goal/정정·실제 개발 작업·결과 사용·중단/재접속까지 GUI로 수행한다. 지원 플랫폼마다 같은 흐름을 확인한다.','사용자 설계 원칙(벤더 독립·OS 독립·SOLID)과 첫 출시 Windows·Linux 결정(2026-10-14) 반영','2026-10-14T01:54:45Z','7bfe400309456daeea3901a655615092cce3ea82731322e4e0b1071fb97908ef','489c58adeaa7068f84142ac4eabc92da8a6dca2ba7022df7dee06ec2dfe672ee');
