INSERT INTO "decisions" VALUES('DEC01','첫 제품은 데스크톱 GUI(Windows·Linux)','confirmed','Windows x64와 Linux x64 데스크톱 GUI로 첫 출시한다. 진행은 Windows를 먼저 한다.','현재 사용자 요구 3번. Windows 세부 지원버전·CPU·installer는 별도 열린 결정. 2026-10-14 사용자 결정으로 Linux를 첫 출시 범위에 추가했다(S-USER-20261014).','S-USER-20261014');
INSERT INTO "decisions" VALUES('DEC02','총괄 에이전트 모델을 사용자가 지정','confirmed','총괄 실행 자원과 모델을 설정할 수 있게 한다.','현재 사용자 요구 2번. 실제 profile 필드와 worker 역할 분리는 제품 설계로 구체화.','S-USER');
INSERT INTO "decisions" VALUES('DEC03','멀티벤더 인증 관리 공간','confirmed','여러 벤더 로그인·API 연결을 한곳에서 관리한다.','현재 사용자 요구 1번. 비밀 저장 backend 선택은 별도 ADR.','S-USER');
INSERT INTO "decisions" VALUES('DEC04','VM·AGS 권위 경계 유지','confirmed','VM은 Goal/Task/Attempt/verdict, AGS는 거버넌스/협업, AIK는 pool/placement/lease를 소유한다.','최초 설계 §3과 VM 권위 설계의 중복 원장 금지 원칙을 유지.','S-DESIGN');
INSERT INTO "decisions" VALUES('DEC05','JEV 보조와 AGENT 최종 선택','confirmed','RAW 보존·앞단 별도 LLM 정형화 없음·최종 스킬 선택 AGENT를 유지한다.','사용자 정정 사항과 최초 설계 §10.','S-JEV');
INSERT INTO "decisions" VALUES('DEC06','첫 단일 클러스터 출시 이후 연합 확장','proposed','M0~M4는 첫 배포(Windows·Linux), M5는 두 클러스터 연합, M6는 확장으로 단계화한다.','GUI/인증/설치형 gate를 먼저 실증하기 위한 개발 순서 제안. 사용자 확정 OS 요구와 구분하며 연합 목표를 제거하지 않음.','S-DESIGN');
INSERT INTO "decisions" VALUES('DEC07','GUI 구현 스택','confirmed','첫 구현 스택을 Electron44.7.0+React19.2.8/TypeScript7.0.2+CPython3.14.8 sidecar로 확정한다. 동일 Windows job의 Tauri2.12.3 대안도 실제 설치·IPC·worker·DPAPI·메모리 관측·제거를 통과했다. 이 결정은 구현 책임자의 기술 선택이다.','동일 frozen engine을 사용한 실제 비교에서 현재 오프라인 runtime 공급 정책의 installer는 Electron113.22MiB·Tauri216.15MiB였다. GUI runtime의 앱 버전 결속 및 현재 Node/Python 빌드·검사 경로 유지 비용을 근거로 Electron을 선택한다. Tauri native working set은 더 작았으나 전체 앱 메모리·속도 우위를 일반화하지 않는다. Windows11 지원 확정이나 실제 벤더·AGS·VM 제품 연동 성공을 뜻하지 않는다.','S-STACK-20261012');
INSERT INTO "decisions" VALUES('DEC08','지원 플랫폼·설치 형식','proposed','Windows11 x64 지원 후보, 사용자별 NSIS EXE, Electron/Python runtime 포함, 정식 Authenticode·서명 설치본 수동 업데이트와 기본 사용자 데이터 보존 정책을 선택했다. Linux x64의 지원 배포판과 설치 형식은 미정이며 AIK-003의 LINUX-X64 행에서 정한다.','Windows Server2022의 실제 설치·제거, 독립 ZIP 재실행 및 기본 PowerShell5.1 전달 경로는 통과했다. 기존 AIK-003의 깨끗한 후보 Windows·개발 도구 없는 환경 검증은 미완료이며, 지원 qualification과 정식 제품 서명 성공을 주장하지 않는다.','S-HANDOFF-20261012');
INSERT INTO "decisions" VALUES('DEC09','플랫폼별 시크릿 backend','proposed','Windows: 사용자 범위 Credential Manager 또는 DPAPI 보호 저장소를 검증해 선택한다(구현 후보 DPAPI). Linux: Secret Service(`secret-tool` CLI, D-Bus 키링)를 쓰고, 키링이나 D-Bus가 없으면 저장을 거절한다(fail-closed, 사용자 결정 2026-10-14). 플랫폼 선택은 OS port 뒤 adapter에서 한다.','비밀 참조 broker는 앱의 접근 범위를 통제한다. Windows 사용자 vault의 저장/사용자 경계와 trusted same-user native 프로세스의 직접 OS 접근 범위를 별도 명시하고 실제 보장만 검증한다. Linux backend는 사용자가 Secret Service를 골랐다(S-USER-20261014). Windows 선택은 아직 제안 상태다.','S-DPAPI');
INSERT INTO "decisions" VALUES('DEC10','AI-Kubernetes 라이선스','open','AIK 자체 라이선스와 재배포 notice를 배포 전에 확정한다.','최초 README는 미정. upstream 라이선스를 AIK 전체에 자동 적용하지 않음.','S-README');
INSERT INTO "decisions" VALUES('DEC11','원격 PEER 전송과 신뢰 계약','open','버전·상호 인증·키 회수·메시지 수명·권위 회복과 입력 manifest/수신 경로 projection·준비 책임을 연합 구현 전에 확정한다.','현재 AGS 동일 사용자 로컬 PEER를 원격 신뢰 도메인과 구분.','S-AGS');
INSERT INTO "decisions" VALUES('DEC12','첫 출시 provider/runtime·역할 지원 matrix','proposed','OpenAI/Anthropic API와 지원 Codex/Claude Code 구독 bridge를 초기 구현 대상으로 삼는다. 두 벤더 및 API/지원 구독·총괄/개발/검토 역할의 필수 조합과 실제 read/create/update/한정 검증 명령을 001 matrix로 정한다. 012~015 adapter 구현, 022 인증, 082 실제 사전 probe, 086 governed qualification, 044 합성 목표, 059/064 설치본 판정을 구분한다.','초기 범위는 제안이며 사용자 확정 요구와 구분한다. 선택 경로의 미지원은 다른 qualified 경로를 막지 않지만 미구현 adapter를 완료 처리하거나 필수 경로를 임의 축소하지 않는다. 범위 변경 시 결정·영향·재검증 기록을 남긴다.','S-DESIGN');
INSERT INTO "decisions" VALUES('DEC13','판본별 제품 완료 계약과 선택 확장 출시','proposed','P01~P10을 첫 출시(Windows·Linux) 인수 흐름, P11을 연합, P12를 확장 흐름으로 관리한다. M5 기본 065/067~075와 M6 기본 076~079는 각각 089/090 새 설치본 gate로 판정한다. 선택 066 Cloud/080 Kubernetes는 scope 확정 시 해당 gate의 실제 선행에 추가하고 미선택은 미완료로 유지한다.','사용자의 완제품 검증 요구에서 도출한 계획 보강이다. 기능 구현과 실제 제품 인계·후속 배포를 연결하며 선택 route와 선택 기능을 구분한다. 첫 Windows 범위를 모든 미래 기능과 혼동하지 않고 범위 변경의 영향·결정·재검증을 기록한다.','S-COMPLETE');
INSERT INTO "decisions" VALUES('DEC14','OS·벤더 port 경계(SOLID)','confirmed','공통 코드는 OS·벤더를 직접 다루지 않고 concern별 좁은 port(파일·잠금·프로세스·경로·시크릿·세션 신호·HTTP transport)에 의존한다. OS 판별은 플랫폼 계층 한 곳에서만 하고, 새 OS·벤더는 adapter 추가로 지원한다(DIP·OCP·ISP).','사용자 설계 원칙(벤더 독립·OS 독립·SOLID). 2026-10-14 OS 감사에서 같은 디렉터리 동기화 헬퍼 13벌, 원자적 쓰기 패턴 17개 파일, 동일한 프로세스 모듈 2벌의 복제와 공통 코드의 벤더 adapter import가 확인됐다.','S-USER-20261014');
INSERT INTO "epics" VALUES('E01','제품·통합 기반','구성요소 소유권, 기술 결정, 프로세스·데이터 기반');
INSERT INTO "epics" VALUES('E02','시크릿·인증','멀티벤더 계정과 비밀 값의 수명주기');
INSERT INTO "epics" VALUES('E03','자원·provider adapter','구독/API/로컬 실행 경로와 실제 capability');
INSERT INTO "epics" VALUES('E04','총괄 에이전트','모델 프로필, 이벤트 기반 운영, 연속성·대체 정책');
INSERT INTO "epics" VALUES('E05','AGS·VM 통합','기존 권위·gate·JEV·설치형 호환 연결');
INSERT INTO "epics" VALUES('E06','배치·worker 수명','lease·배치·관측·회수·실패 복구');
INSERT INTO "epics" VALUES('E07','관측·감사·비용','근거·권한·정산·운영 상태');
INSERT INTO "epics" VALUES('E08','데스크톱 GUI','인증·설정·작업·승인·결과·현황 화면');
INSERT INTO "epics" VALUES('E09','출시·패키징','플랫폼별 설치·업데이트·qualification·독립 검토');
INSERT INTO "epics" VALUES('E10','클러스터 연합','PEER 신뢰·위임·원격 관측·복구');
INSERT INTO "epics" VALUES('E11','후속 확장','추가 자원·정책·조직·실제 Kubernetes 연결');
INSERT INTO "epics" VALUES('E12','플랫폼 독립 계층','OS port·플랫폼 adapter와 공통 코드의 OS·벤더 결합 제거');
INSERT INTO "external_dependencies" VALUES('EXT-VM-POSIX-D1','vm','VibeMarshal RuntimeJob owner lock의 POSIX 지원','open','vibemarshal src/flowmarshal/engine/runtime.py (os.name == ''nt'', msvcrt 잠금; POSIX는 fail-closed, VM 결정 D1)','VM은 수정하지 않는 고정 계약이다. VM이 POSIX 잠금을 지원할 때까지 Linux에서 VM 실제 실행에 의존하는 플랫폼 행은 완료할 수 없다.');
INSERT INTO "external_dependencies" VALUES('EXT-AGS-A2-HOSTINTEGRATION','ags','AGS host-integration.json(HostIntegration.v1)과 A2 profile의 main 반영','open','agent-governance-suite main 2.9.0(56fef8bd)에 없음; 리뷰 후보 codex/v260-semantic-decision-layer','AGS는 수정하지 않는 고정 계약이다. 반영 전에는 실제 A2 적합성 PASS가 불가능하다.');
