INSERT INTO "metadata" VALUES('design_principles','PRN-VENDOR, PRN-OS, PRN-SOLID (S-USER-20261014)');
INSERT INTO "metadata" VALUES('platform_policy','tasks.status is the overall state and task_platforms holds per-platform state. A done task needs every platform row done or not_applicable; a done platform row needs evidence for that platform or platform-neutral evidence; an open external prerequisite blocks completion.');
INSERT INTO "milestones" VALUES('M0','통합 계약·플랫폼 기반 결정',0,'first_release','소유권·실제 runtime 주입점·지원 환경과 P01~P12 최소 제품 인수 계약/독립 oracle/측정 조건을 고정하고 GUI·저장 기반을 준비한다. OS 차이는 port 뒤 플랫폼 adapter로 분리한다(AIK-091).');
INSERT INTO "milestones" VALUES('M1','인증 보관·멀티벤더 자원 연결',1,'first_release','후보 adapter 코드를 구현하고, 같은 지원 matrix의 필수 두 벤더 API/지원 구독 인증 경로와 vault를 지원 플랫폼(Windows·Linux)마다 실제로 검증한다. 선택 미지원 경로는 별도 결과로 유지한다.');
INSERT INTO "milestones" VALUES('M2','총괄 에이전트·AGS/VM 실행 통합',2,'first_release','실제 workspace와 native/API 개발 도구를 VM/AGS 권위에 결속하고 사전 probe 뒤 필수 역할/효과 qualification 및 두 벤더 A/B→C 생성·수정·검증 실패 후 재작업·인계 E2E를 통과한다.');
INSERT INTO "milestones" VALUES('M3','데스크톱 GUI 실제 연결',3,'first_release','사용자 프로젝트 선택부터 인증·총괄/worker 모델 지정·RAW Goal/정정·실제 개발 작업·결과 사용·중단/재접속까지 GUI로 수행한다. 지원 플랫폼마다 같은 흐름을 확인한다.');
INSERT INTO "milestones" VALUES('M4','첫 배포 검증(Windows·Linux)',4,'first_release','같은 source commit의 지원 플랫폼별 설치본에서 각각 P01~P10, 일관 백업/GUI 복원·실패 회복·독립 검토·고정 품질/성능 기준을 모두 통과하고 064 release manifest로 배포한다.');
INSERT INTO "milestones" VALUES('M5','탄력 운영·원격 PEER 연합',5,'follow_up','기본 065/067~075와 선택한 066을 089의 실제 선행에 결속하고 새 지원 플랫폼 설치본에서 P01~P10 회귀와 P11 실제 두 클러스터 입력·쓰기/검증·결과·복구/비용을 통과해 출시한다. 미선택 066은 미완료로 유지한다.');
INSERT INTO "milestones" VALUES('M6','추가 자원·조직·배포 확장',6,'future','제안 기본 076~079와 선택한 080을 090의 실제 선행에 결속하고 새 지원 플랫폼 설치본에서 P01~P11 회귀와 P12 확장별 실제 GUI/역할/작업/복구를 통과해 출시한다. 미선택 080은 미완료로 유지하며 전체 로드맵 완료와 구분한다.');
INSERT INTO "platforms" VALUES('WIN-X64','Windows x64','windows','first_release','지원 버전·설치 형식은 DEC08/AIK-003. 진행 우선 플랫폼.');
INSERT INTO "platforms" VALUES('LINUX-X64','Linux x64','linux','first_release','지원 배포판·설치 형식은 미정(DEC08/AIK-003). VM 실행 의존 부분은 EXT-VM-POSIX-D1 외부 선행.');
INSERT INTO "principles" VALUES('PRN-VENDOR','벤더 독립','벤더 독립은 무조건 지킨다. 공통 계약·저장소·GUI는 특정 벤더를 모르고, 벤더 차이는 adapter에만 둔다. 공통 코드는 벤더 adapter 모듈을 import하지 않는다.','S-USER-20261014');
INSERT INTO "principles" VALUES('PRN-OS','운영체제 독립','공통 코드는 운영체제를 모른다. 파일·잠금·프로세스·경로·시크릿·세션 신호의 OS 차이는 port 뒤 플랫폼 adapter에만 두고, OS 판별은 플랫폼 계층 한 곳에서만 한다.','S-USER-20261014');
INSERT INTO "principles" VALUES('PRN-SOLID','SOLID','단일 책임과 좁은 인터페이스(ISP), 추상에 대한 의존(DIP)을 지키고, 새 OS·벤더는 기존 코드 수정이 아니라 adapter 추가로 지원한다(OCP).','S-USER-20261014');
INSERT INTO "requirements" VALUES('U01','user','멀티벤더 로그인 시크릿 공간','여러 벤더의 계정·구독 연결·API 키를 GUI의 한 공간에서 등록·확인·교체·해제한다.');
INSERT INTO "requirements" VALUES('U02','user','Dot 역할 총괄 에이전트의 모델 지정','사용자가 총괄 역할에 사용할 모델과 실행 자원을 지정하고 해당 에이전트가 목표·위임·보고를 지속한다.');
INSERT INTO "requirements" VALUES('U03','user','GUI 제품','핵심 연결·총괄 설정·작업 운영·결과 확인을 GUI에서 수행한다.');
INSERT INTO "requirements" VALUES('U04','user','첫 출시 Windows·Linux','첫 제품 배포와 완료조건은 지원 플랫폼 Windows x64와 Linux x64를 대상으로 한다. 진행은 Windows를 먼저 하고, Linux에서 VM 실행에 의존하는 부분은 VM POSIX 지원(외부 선행 EXT-VM-POSIX-D1)이 해소될 때까지 차단으로 둔다. macOS 출시는 선행조건으로 두지 않는다.');
INSERT INTO "requirements" VALUES('U05','user','구독·API·로컬을 장착형 자원으로 통합','구독/API/로컬 모델을 공통 ResourcePool로 다루며 실행 경로별 인증과 능력 차이는 adapter가 보존한다.');
INSERT INTO "requirements" VALUES('U06','user','필요할 때 확장하고 반환하는 worker','독립 작업을 제약 내에서 병렬 실행하고 결과·증거·사용량을 회수한 뒤 자원을 반환한다.');
INSERT INTO "requirements" VALUES('U07','user','AI-Kubernetes 클러스터 간 PEER 연합','독립 클러스터들이 자기 권한과 인증정보를 유지하면서 작업을 위임하고 결과를 회수한다.');
INSERT INTO "requirements" VALUES('U08','user','AGS와 VibeMarshal을 기반으로 구축','기존 AGS 거버넌스·PEER와 VM 계획/실행/복구 권위를 재사용한다.');
INSERT INTO "requirements" VALUES('U09','user','JEV는 내부 보조 계층이며 최종 선택은 AGENT','RAW를 보존하고 앞단 별도 LLM 정형화 없이 확인된 metadata만 구조화한다. JEV가 스킬 선택을 강제하지 않는다.');
INSERT INTO "requirements" VALUES('D01','derived','비밀 값과 비밀 참조 분리','실비밀은 OS 사용자 범위 vault(Windows DPAPI·Linux Secret Service) 또는 공식 호스트 저장소에 둔다. 프롬프트·장부·PEER·로그에는 참조와 비민감 metadata만 사용한다.');
INSERT INTO "requirements" VALUES('D02','derived','설정값·실제 관측값·역할 분리','총괄과 worker 프로필을 분리하고 requested/provider_observed/configured_catalog를 혼동하지 않는다.');
INSERT INTO "requirements" VALUES('D03','derived','총괄 지속성과 GUI 수명 분리','이벤트 큐·동일 인스턴스 보장·재시작 회복으로 창을 다시 열어도 기존 목표와 실행을 이어간다.');
INSERT INTO "requirements" VALUES('D04','derived','실행 권위와 중복 방지','VM Goal/Task/Attempt 권위와 AIK lease/placement 소유권을 유지하고 불명확한 실행의 자동 중복 발사를 막는다.');
INSERT INTO "requirements" VALUES('D05','derived','자원·예산·쿼터·권한에 따른 배치','실행 capability, 인가, 동시성, 예산, 데이터 경계를 확인하고 실제 사용량과 예약을 정산한다.');
INSERT INTO "requirements" VALUES('D06','derived','근거에 따른 완료와 통합 검증','ACK·실행 성공·검증·GoalVerdict를 구분하고 실제 설치형 경로의 검증 근거로 완료한다.');
INSERT INTO "requirements" VALUES('D07','derived','플랫폼 운영성과 배포 품질','설치·업데이트·한글 UI·접근성·실패 복구·진단 및 동작 측정을 첫 출시 지원 플랫폼마다 검증한다.');
INSERT INTO "requirements" VALUES('D08','derived','AGS/VM 호환성과 미완료 gate 해소','현재 문서에 남은 A2 conformance·model/effort 관측·GUI mock 경계를 실제 배포물 검증으로 해소한다.');
INSERT INTO "requirements" VALUES('P01','derived','설치 후 멀티벤더 인증의 전체 수명주기','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 개발 도구 없는 지원 플랫폼에 설치하고 GUI에서 두 벤더의 필수 API/지원 구독 경로를 연결한 뒤 만료·재인증·계정 교체·해제를 수행한다. 통과: 고정 matrix의 실제 계정/connection binding과 인증 상태가 일치하고 교체 후 다음 실행이 선택 계정으로 전달된다. 차단: 필수 경로 미지원/NOT_RUN, 외부 로그인 변경의 묵시 계정 전환, fixture만의 성공, 수동 CLI 사전 설정. 선택 경로의 unsupported는 별도 표시한다.');
INSERT INTO "requirements" VALUES('P02','derived','사용자 프로젝트 선택과 실제 실행 입력 결속','범위: 첫 출시(지원 플랫폼 각각). 시나리오: GUI에서 기존 한글/공백 경로 프로젝트를 열고 새 폴더를 만들며 다른 프로젝트로 전환한다. 통과: 화면 workspace, VM project/root, native/API cwd, 허용 입력·선행 산출물의 bytes/digest/revision이 실제 실행과 일치하고 재시작 뒤 유지된다. 차단: 샘플 root 대체, 다른 workspace 쓰기, 누락/변조/stale 입력, 허용 root를 벗어난 경로 또는 해석 불가 참조. 이동·권한 상실은 안내와 재결속 절차로 처리한다.');
INSERT INTO "requirements" VALUES('P03','derived','총괄·개발·검토 모델 지정의 실효성','범위: 첫 출시(지원 플랫폼 각각). 시나리오: GUI에서 총괄과 개발/검토 역할에 서로 다른 connection/model/지원 effort를 지정하고 실제 목표를 수행한다. 통과: 역할별 요청값과 provider 관측값, Attempt/lease/job/계정 binding이 근거로 대조되며 허용 fallback만 적용된다. 차단: 설정값을 실측으로 표시, 다른 계정/모델로 묵시 routing, 미관측 필드의 추정, 운영 미검증 자원의 qualified 광고. 읽기 전용 분석 역할과 파일/검증 도구를 가진 개발 역할의 지원 능력을 구분한다.');
INSERT INTO "requirements" VALUES('P04','derived','RAW 목표에서 의존 작업·실제 수정·검증·재작업까지','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 사용자가 고른 프로젝트에 RAW Goal 하나를 제출하고 실제 총괄/VM 준비 경로가 A·B 독립 작업과 두 결과를 소비하는 C를 구성한다. 두 벤더 자원이 실제 파일을 생성/수정하고 한정된 검증 명령을 실행한다. 통과: 독립 검사에 의도적으로 한 번 실패한 뒤 기존 인가·VM 재작업 절차로 수정해 최종 Goal Test와 사용 가능한 산출물을 얻는다. 후속 정정도 같은 Goal의 올바른 revision에 반영한다. 차단: 미리 넣은 Plan/Task/완성 출력, 후속 입력 미전달, 검사 생략·기준 임의 수정, 모델 자기선언만의 성공, stale 인가. VM 직렬 기본과 qualification된 병렬 범위를 유지한다.');
INSERT INTO "requirements" VALUES('P05','derived','인가·비밀·사용량 한도를 지키는 실제 실행','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 허용된 프로젝트 작업을 실행하고 범위 확대·다른 workspace·예산/동시성 한도·만료 인증을 각각 시도한다. 통과: 기존 인가는 반복 질문 없이 전달되고 확대 또는 stale 요청만 기존 VM/AGS 절차로 중단되며 GUI가 구체 이유와 다음 행동을 표시한다. 합성 비밀을 이용해 prompt/로그/IPC/근거/지원 번들 노출과 실제 OS trust profile을 검사한다. 차단: 우회 도구 실행, 권한 자가 부여, 무제한/0으로 꾸민 unknown usage, 실제보다 강한 native 격리 주장.');
INSERT INTO "requirements" VALUES('P06','derived','개별 도구 효과·취소·중단 이후의 안전한 회복','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 실제 임시 프로젝트 파일 변경에서 effect 전 intent, effect 후 receipt, 모델에 도구 결과를 반환하는 각 경계에 중단·취소·늦은 결과를 주입한다. 통과: tool_call/effect identity와 request digest가 Attempt/인가/lease에 연결되고 같은 효과가 중복되지 않으며 기존 결과 재전송 또는 VM unknown/reconciliation으로 수렴한다. 차단: provider job 조회만으로 도구 효과 성공을 추정하거나 불명확한 비멱등 효과를 자동 재실행. 임의 외부 명령에 exactly-once를 주장하지 않는다.');
INSERT INTO "requirements" VALUES('P07','derived','완성 산출물의 사용자 인계와 보존','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 합성 목표의 최종 파일·검증 근거를 GUI에서 열고 저장/내보낸 뒤 worker 반환과 앱 재시작 후 다시 사용한다. 통과: 사용자가 받은 bytes/digest와 VM verdict의 산출물/검토 근거가 일치하고 약속한 보관 범위에서 유지되며 후속 Task 입력도 같은 권위 참조에 결속된다. 차단: 종료된 임시 worker 경로만 제공, 깨진 다운로드, 표시용 derivative를 원본 근거로 대체, unsafe 결과 콘텐츠의 자동 실행. 보관 만료·외부 파일 변경은 명확히 표시한다.');
INSERT INTO "requirements" VALUES('P08','derived','GUI 감독의 연속성과 자원 반환','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 목표 실행 중 창 닫기/재열기, 앱/sidecar 재시작, 일시정지·재개·취소를 수행한다. 통과: 같은 Goal·대화·미처리 지시·진행 job·인가 revision을 복원하고 requested/observed 모델·상태·usage·unknown 이유를 조회한다. 신규 배치 중지와 실제 종료를 구분하며 자체 worker만 종료하고 borrowed host는 lease를 반환한다. 차단: 새 Goal 중복 생성, 미처리 지시 유실, 유휴 무한 모델 호출, 회수되지 않는 lease 또는 사용자 호스트 강제 종료.');
INSERT INTO "requirements" VALUES('P09','derived','GUI 유지보수와 일관된 제품 상태 복원','범위: 첫 출시(지원 플랫폼 각각). 시나리오: GUI에서 비밀 없는 설정 이동과 제품 상태 백업을 구분해 수행하고, 업데이트 중단 또는 새 OS 사용자에서 설치본의 복구 화면으로 복원·재인증한다. 통과: AIK 설정, VM Goal/Attempt, AGS 근거, 실제 artifact가 각 소유자의 공개 checkpoint/복원 절차와 공통 manifest로 같은 복구 지점에 맞고 완료 이력이 열린다. 실행 중/unknown 외부 job은 조회·reconciliation 후 처리한다. 차단: 서로 다른 시점의 DB를 참조 문자열만 맞춰 성공 처리, dangling evidence, 자동 중복 효과, CLI/소스 checkout 필수. 앱 부팅 실패 때도 제공되는 복구 진입점이 있다.');
INSERT INTO "requirements" VALUES('P10','derived','고정 설치본의 품질·지원·출시 판정(플랫폼별)','범위: 첫 출시(지원 플랫폼 각각). 시나리오: 하나의 commit/installer hash·runtime manifest·지원 matrix 판본에 P01~P09, 깨끗한 설치/제거, 한글/키보드/접근성, 장애·비밀·성능·지원 안내 검증을 연결한다. 통과: AIK-003/083에서 측정 전에 고정한 hardware/부하/지속시간과 응답·메모리·사용량 한도에 대한 독립 결과가 충족되고 release notes/지원 주장과 일치한다. 차단: 필수 FAIL/NOT_RUN/미해결 중대 결함, 다른 빌드의 혼합 근거, 사후 임계값 완화, 개발 환경만의 성공. 우선순위 P1도 첫 출시 범위이면 필수다.');
INSERT INTO "requirements" VALUES('P11','derived','연합 기능을 포함한 실제 후속 출시','범위: M5 후속 출시. 시나리오: 연합 기능이 포함된 새 설치본으로 이전 지원 버전에서 업그레이드하고 두 실제 독립 클러스터를 GUI로 연결해 송신 측에만 있던 입력·선행 산출물을 다른 root에 준비하여 의존 쓰기/검증 작업과 결과 회수를 수행한다. 통과: 단절·중복/역전·취소·재시작 후 권위/효과/근거/비용이 회복되고 P01~P10 회귀와 연합 지원 matrix가 같은 새 빌드에서 통과한다. 차단: 전 경로 NOT_RUN, 수동 입력 사전 복제, 개발 모드만의 E2E, M4 옛 설치본 근거 재사용. 066 Cloud 생성은 별도 선택이며 선택 시 089의 실제 선행으로 추가하고 필수 live 검증한다.');
INSERT INTO "requirements" VALUES('P12','derived','선택한 추가 자원을 포함한 실제 확장 출시','범위: M6 확장 출시. 현재 제안 기본 프로필은 076~079의 로컬 LLM·추가 adapter SDK·정책 템플릿·조직 위임이다. 시나리오: 새 설치본에서 각 선언 기능을 GUI로 설정해 실제 governed 작업·근거 회수와 이전 버전 업그레이드/복원을 수행한다. 통과: 고정 지원 matrix의 필수 runtime/역할/도구 및 P01~P11 회귀가 같은 새 빌드에서 통과한다. 차단: adapter fixture만의 성공, 패키징 누락, 이전 gate의 근거 재사용. 080 Kubernetes는 독립 선택 기능으로 선택 시 090의 실제 선행에 추가하고 live 검증하며, 미선택은 todo/future로 유지해 전체 90개 완료라고 주장하지 않는다. 범위 변경은 영향·결정·의존성·재검증 기록을 요구한다.');
INSERT INTO "requirements" VALUES('U10','user','OS 독립 구조','공통 코드는 운영체제를 모른다. 파일·잠금·프로세스·경로·시크릿·세션 신호 같은 OS 차이는 port 뒤 플랫폼 adapter에만 두고, 새 OS 지원은 adapter 추가로 한다.');
INSERT INTO "requirements" VALUES('U11','user','벤더 독립 구조','공통 계약·저장소·GUI는 특정 벤더를 모른다. 벤더 차이는 adapter에만 두고 공통 코드는 벤더 adapter 모듈을 import하거나 벤더 목록을 하드코딩하지 않는다.');
INSERT INTO "sources" VALUES('S-USER','현재 사용자 요청: 인증 공간·총괄 모델·Windows GUI','user','','2026-10-12','사용자가 개발 태스크를 SQLite로 정리하여 AI-Kubernetes에 push하도록 요청. 3개 추가 요구를 직접 확정.');
INSERT INTO "sources" VALUES('S-VISION','첨부 대화의 AI-Kubernetes 사용자 확정 비전','user','','2026-10-12','구독/API/로컬 자원 장착, 탄력 worker, AGS+VM, 클러스터 간 PEER. 이전 assistant의 비유나 구현 추정은 완료 근거로 사용하지 않음.');
INSERT INTO "sources" VALUES('S-JEV','사용자가 확정한 JEV 및 최종 AGENT 선택 원칙','user','','2026-10-08','JEV는 AGS/VM 내부 보조 계층. RAW 보존, 앞단 별도 LLM 정형화 없음, 최종 스킬 선택은 실제 AGENT.');
INSERT INTO "sources" VALUES('S-README','AI-Kubernetes 최초 README','repository','https://github.com/jaeseongs95/AI-Kubernetes/blob/0367932ce2fa9369a3420a4867283167ea319188/README.md','0367932ce2fa9369a3420a4867283167ea319188','문서 확인. 저장소 전체 tree에는 README와 최초 설계만 존재; 제품 구현·검증 결과 없음.');
INSERT INTO "sources" VALUES('S-DESIGN','AI-Kubernetes 최초 설계 v0.1','repository','https://github.com/jaeseongs95/AI-Kubernetes/blob/0367932ce2fa9369a3420a4867283167ea319188/docs/initial-design.ko.md','0367932ce2fa9369a3420a4867283167ea319188','문서 확인. VM 권위 원장, AIK placement/lease, AGS 거버넌스 경계와 연합 비전을 유지.');
INSERT INTO "sources" VALUES('S-AGS','AGS README 기준선','repository','https://github.com/jaeseongs95/agent-governance-suite/blob/56fef8bd189377b80f4020f506e717ab292b260a/README.md','56fef8bd189377b80f4020f506e717ab292b260a','README는 2.9.0 공개 준비와 동일 컴퓨터·동일 OS 사용자 기본 범위를 설명. 이번 작업에서 제품 코드를 실행하지 않음.');
INSERT INTO "sources" VALUES('S-AGS-ATTEST','AGS host execution attestation 계약','repository','https://github.com/jaeseongs95/agent-governance-suite/blob/56fef8bd189377b80f4020f506e717ab292b260a/docs/host-execution-attestation.md','56fef8bd189377b80f4020f506e717ab292b260a','문서 확인. 실제 배포물 manifest와 runtime 관측 증거의 설치형 검증은 별도 태스크.');
INSERT INTO "sources" VALUES('S-VM','VibeMarshal README 기준선','repository','https://github.com/jaeseongs95/vibemarshal/blob/32bb0f9dd9f024045d24487312b50f5b703573a3/README.md','32bb0f9dd9f024045d24487312b50f5b703573a3','0.2.0a1; schema 4/RuntimeJob/façade 구현 명시, 1.0 NO-GO, GUI mock. A2 호환 gate와 Codex model/effort 관측에 미완료 조건 명시. 실행 미검증.');
INSERT INTO "sources" VALUES('S-VM-GUI','VM GUI 인터페이스 설계','repository','https://github.com/jaeseongs95/vibemarshal/blob/32bb0f9dd9f024045d24487312b50f5b703573a3/docs/gui-interface-design.md','32bb0f9dd9f024045d24487312b50f5b703573a3','Tauri 2+React/TypeScript+Python sidecar 제안과 비권위 EngineClient를 재사용 후보로 검토. schema2 예시와 현재 schema4 차이 확인 필요.');
INSERT INTO "sources" VALUES('S-VM-CORE','VM orchestration 권위 설계','repository','https://github.com/jaeseongs95/vibemarshal/blob/32bb0f9dd9f024045d24487312b50f5b703573a3/docs/orchestration-redesign.md','32bb0f9dd9f024045d24487312b50f5b703573a3','Goal/Plan/Task/Attempt 및 verdict는 VM 권위. README와 일부 freeze/qualification 상태 서술 차이는 설치본 증거로 해결.');
INSERT INTO "sources" VALUES('S-DPAPI','Microsoft CryptProtectData','official_doc','https://learn.microsoft.com/en-us/windows/win32/api/dpapi/nf-dpapi-cryptprotectdata','accessed 2026-10-12','Windows 사용자 범위 DPAPI 검토 근거. 머신 범위를 기본으로 선택하지 않음. 일반적인 동일 사용자/기기 경계와 예외를 구분.');
INSERT INTO "sources" VALUES('S-CRED','Microsoft Credential Manager CredWrite','official_doc','https://learn.microsoft.com/en-us/windows/win32/api/wincred/nf-wincred-credwritea','accessed 2026-10-12','Windows 사용자 자격 증명 생성·교체 API 후보. 구체 vault backend는 ADR로 확정.');
INSERT INTO "sources" VALUES('S-CREDREAD','Microsoft CredRead: 현재 로그온 token의 사용자 자격 증명 조회','official_doc','https://learn.microsoft.com/en-us/windows/win32/api/wincred/nf-wincred-credreada','2026-10-12 조회','Windows 사용자 저장소의 접근 경계에 관한 공식 문서. 앱 broker scope가 동일 사용자 native 프로세스의 OS API 접근을 자동으로 제한한다는 근거는 아니다.');
INSERT INTO "sources" VALUES('S-COMPLETE','사용자의 태스크→완제품 완료성 검증 요청','user','','2026-10-12','태스크를 그대로 따라 개발하면 완제품이 나오는지 검증하라는 요청. 반례 감사와 최소 제품 인수 조건을 도출했으며 사용자 확정 요구·기존 권위 경계를 유지한다.');
INSERT INTO "sources" VALUES('S-VM-RUNTIME','VM의 설치형 application/runtime 주입·dispatch·intent 계약','repository','https://github.com/jaeseongs95/vibemarshal/blob/32bb0f9dd9f024045d24487312b50f5b703573a3/src/flowmarshal/engine/runtime.py','32bb0f9dd9f024045d24487312b50f5b703573a3','동일 SHA의 engine/application.py·runtime.py·cli.py 및 engine-user-workflow.md 읽기. 단일 runtime 객체 주입 seam과 VM 내부 Attempt/intent 예약을 확인했으며 AIK route/lease/effect의 효과 전 결속은 선행 통합 계약·설치형 검증 대상이다. upstream 코드 import/실행 없음.');
INSERT INTO "sources" VALUES('S-IMPL-20261012','Windows 기반 구현·설치형 연동 실제 검증','repository','https://github.com/jaeseongs95/AI-Kubernetes/commit/56523355d9cf3a2437989d1dd26f2e5ced1666d2','56523355d9cf3a2437989d1dd26f2e5ced1666d2','기존 태스크 구현 지시에 따른 기술 선택과 실제 실행 증거. 특정 기술을 사용자가 직접 선택한 요구로 간주하지 않는다. Windows CI38219549819 PASS 범위와 미실행 조건은 evidence/에 보존한다.');
INSERT INTO "sources" VALUES('S-STACK-20261012','Electron·Tauri 실제 Windows 비교와 첫 구현 스택 결정','repository','https://github.com/jaeseongs95/AI-Kubernetes/commit/a20d3bef3f4865fc81cd3495ecc437b7a9b57cea','a20d3bef3f4865fc81cd3495ecc437b7a9b57cea','Windows CI38223818838의 같은 job·같은 frozen engine으로 두 후보 설치·GUI·IPC·worker·DPAPI·메모리 관측·제거를 실제 검증했다. Electron 선택은 기존 개발 지시에 따른 구현 결정이며 사용자가 특정 GUI 기술을 지정했다는 뜻은 아니다. Windows11 clean 및 제품 qualification은 별도 미실행이다.');
INSERT INTO "sources" VALUES('S-HANDOFF-20261012','독립 Windows 설치 ZIP·기본 PowerShell5.1 실제 검증','repository','https://github.com/jaeseongs95/AI-Kubernetes/commit/4b948f57020f3e507683de6e538544b9bac558e7','4b948f57020f3e507683de6e538544b9bac558e7','Windows CI38226204128: 신규 전달 ZIP의 실제 설치·GUI·sidecar·worker·DPAPI·제거 PASS. 실제5.1/Windows-1252에서 원본parse2오류/BOM0오류. 최초 모듈조회 실패와 .NETSHA256 수정 기록 보존. 깨끗한 Windows11·실제 개발 도구 부재 및 완제품은 NOT_RUN.');
INSERT INTO "sources" VALUES('S-USER-20261014','사용자 설계 원칙: 벤더 독립·OS 독립·SOLID와 첫 출시 Windows·Linux','user','','2026-10-14','사용자 원문: "나의 철학은 1. 밴더 독립은 무조건 지킨다 2. 운영체제에도 독립적이어야한다 3. SOLID 원칙을 좋아한다". 출시 OS는 Windows·Linux 둘 다(진행은 Windows 우선), Linux 비밀 저장은 Secret Service, 원장은 스키마까지 개편.');
